local config = {
  ui_story_5085_50850100_1_dialog_content = "Aduh, kepalaku...",
  ui_story_5085_50850100_2_dialog_content = "Rasanya seperti... Saya menelan banyak air laut...",
  ui_story_5085_50850100_3_dialog_content = "<color=#e8d9bb>Fwoosh, Fwoosh—</color>",
  ui_story_5085_50850100_4_dialog_content = "Ugh, aku sangat bosan dengan suara ombak... Tunggu, apakah aku benar-benar di pantai?",
  ui_story_5085_50850100_5_dialog_content = "Oh... Akhirnya kamu bangun juga? Bagaimana keadaanmu?",
  ui_story_5085_50850100_6_dialog_content = "Vice…?",
  ui_story_5085_50850100_7_dialog_content = "Matahari sangat terang... Di mana kita?",
  ui_story_5085_50850100_8_dialog_content = "Ah! Kamu sudah bangun!",
  ui_story_5085_50850100_10_dialog_content = "Hah...? K-Kamu bukan Vice!",
  ui_story_5085_50850100_11_dialog_content = "Maaf, aku pikir kamu orang lain! Tunggu... Seharusnya aku berterima kasih padamu karena telah menyelamatkan hidupku...",
  ui_story_5085_50850100_12_dialog_content = "Tenanglah, saya hanya melakukan apa yang saya bisa untuk membantu.",
  ui_story_5085_50850100_13_dialog_content = "Kamu adalah orang pertama yang aku temui di <color=#FFB400>dunia baru</color> ini, tahu!",
  ui_story_5085_50850100_14_dialog_content = "Berdasarkan situasimu, sepertinya kita tidak berada di dunia Oren lagi. Ini bisa menjadi masalah...",
  ui_story_5085_50850100_15_dialog_content = "Apa itu Oren? Tunggu... Apakah kamu bilang \"dunia baru\"?!",
  ui_story_5085_50850100_16_dialog_content = "Benar sekali!",
  ui_story_5085_50850100_17_dialog_content = "Teman-teman dan saya sedang meneliti cara untuk pergi ke akhirat...",
  ui_story_5085_50850100_18_dialog_content = "Tapi kemudian ada yang salah dengan portal itu, dan kita berakhir di sini!",
  ui_story_5085_50850100_19_dialog_content = "Meski dengan semua pengalaman bertualangku, aku tidak tahu bagaimana melanjutkan! Jadi, teman—",
  ui_story_5085_50850100_20_dialog_content = "Apakah kamu keberatan memperkenalkan dunia ini padaku?",
  ui_story_5085_50850100_21_dialog_content = "Memperkenalkan... dunia...?",
  ui_story_5085_50850100_22_dialog_content = "<color=#e8d9bb>Aduh—Aduh—</color>",
  ui_story_5085_50850100_23_dialog_content = "... Dan itu kurang lebih cerita tentang Astra.",
  ui_story_5085_50850100_24_dialog_content = "Tapi saya tidak berpikir kita masih di daratan utama. Jika ada, ini terlihat seperti pulau di lepas pantai Astra.",
  ui_story_5085_50850100_25_dialog_content = "PlayerName! Courier Union baru saja mengirimkan berita terbaru tentang beberapa reruntuhan yang mereka temukan di sebuah pulau!",
  ui_story_5085_50850100_26_dialog_content = "Oh? Maksudmu reruntuhan pulau yang sedang dibicarakan semua orang akhir-akhir ini?",
  ui_story_5085_50850100_27_dialog_content = "Benar! Rupanya, mereka berasal dari kerajaan Aurorian kuno yang jarang muncul dalam catatan sejarah.",
  ui_story_5085_50850100_28_dialog_content = "Beberapa sarjana berpikir bahwa kerajaan ini dapat mengisi kekosongan yang muncul setelah Aurorians meninggalkan Northland!",
  ui_story_5085_50850100_29_dialog_content = "Lumopolis dan Umbraton sudah mulai bersiap untuk menyelidiki pulau itu, dan mereka menawarkan komisi besar bagi siapa saja yang membantu dalam penjelajahan mereka!",
  ui_story_5085_50850100_30_dialog_content = "D-Dikau bilang \"komisi besar\"?!",
  ui_story_5085_50850100_31_dialog_content = "Kami... Kami belum terlambat untuk mendaftar, bukan?!",
  ui_story_5085_50850100_32_dialog_content = "Hihi, aku tahu kamu akan tertarik!",
  ui_story_5085_50850100_33_dialog_content = "Dan jangan khawatir tentang biaya perjalanan. Saya sudah berbicara dengan beberapa orang yang juga akan ke sana.",
  ui_story_5085_50850100_34_dialog_content = "Semua orang setuju untuk bertemu dan pergi bersama untuk mengurangi biaya perjalanan!",
  ui_story_5085_50850100_35_dialog_content = "Saya hanya perlu kamu untuk memeriksa ulang detail perjalanan dengan mereka sebelum kita pergi.",
  ui_story_5085_50850100_36_dialog_content = "Kamu sangat teliti... Baiklah, aku akan melakukan pemeriksaan terakhir sekarang!",
  ui_story_5085_50850100_37_dialog_content = "PlayerName! Aku ingin pergi ke pulau dan mencari musik dari kerajaan kuno!",
  ui_story_5085_50850100_38_dialog_content = "Aku yakin ini akan membuat penampilan Redieselku lebih panas dari sebelumnya! Kamu hanya perlu membawaku bersama!",
  ui_story_5085_50850100_39_dialog_content = "Tentu, bukan masalah!",
  ui_story_5085_50850100_40_dialog_content = "Ada rumor tentang mechs kuno di reruntuhan. Rasa penasaranku semakin menguasai diri. Aku harus melihatnya sendiri.",
  ui_story_5085_50850100_41_dialog_content = "Tolong, PlayerName!",
  ui_story_5085_50850100_42_dialog_content = "Tidak ada keberatan di sini!",
  ui_story_5085_50850100_43_dialog_content = "M-Mari kita buat satu hal jelas! Saya tidak pergi karena saya ingin menghabiskan waktu di pantai musim panas ini...",
  ui_story_5085_50850100_44_dialog_content = "Baru saja aku melihat betapa kerasnya Vice bekerja untuk mempersiapkan perjalanan ini... Aku tidak ingin dia berlebihan, jadi aku pikir aku harus ikut serta.",
  ui_story_5085_50850100_45_dialog_content = "Tentu saja, sangat dihargai, Zarya!",
  ui_story_5085_50850100_46_dialog_content = "<color=#e8d9bb>Dengan tim yang terdiri dari lima orang sekarang terpilih, rombongan berangkat untuk petualangan pulau yang menarik...</color>",
  ui_story_5085_50850100_47_dialog_content = "Semua orang ada di sini? Bagus! Sekarang mari kita berangkat menuju tujuan kita—",
  ui_story_5085_50850100_48_dialog_content = "Ke reruntuhan pulau!",
  ui_story_5085_50850100_49_dialog_content = "Saya berharap kita menemukan beberapa instrumen musik kuno!",
  ui_story_5085_50850100_50_dialog_content = "Atau beberapa mecha kuno legendaris!",
  ui_story_5085_50850100_51_dialog_content = "Pulau ini pasti menyimpan banyak misteri.",
  ui_story_5085_50850100_52_dialog_content = "(Vice dan yang lainnya... mereka semua tampak sedikit terlalu optimis tentang perjalanan ini.)",
  ui_story_5085_50850100_53_dialog_content = "(Orang biasanya kembali dari petualangan seperti ini dengan tangan kosong... Tapi mungkin aku terlalu negatif.)",
  ui_story_5085_50850100_54_dialog_content = "PlayerName, Tuan Corax sedang memanggil!",
  ui_story_5085_50850100_55_dialog_content = "Saya dengar kamu sedang dalam perjalanan ke reruntuhan pulau. Benarkah itu?",
  ui_story_5085_50850100_56_dialog_content = "Saya benar-benar ingin kamu bergabung denganku dalam ekspedisi ini, dan mencari pengetahuan medis Aurorian yang hilang, tetapi tampaknya saya terlambat.",
  ui_story_5085_50850100_57_dialog_content = "Bahkan kamu juga?!",
  ui_story_5085_50850100_58_dialog_content = "Maaf... Banyak orang yang telah meminta dengan alasan yang serupa.",
  ui_story_5085_50850100_59_dialog_content = "Menjelajahi reruntuhan tidak pernah menjadi urusan yang sederhana. Semoga, tim yang telah Anda kumpulkan mencakup pejuang dan medis yang mampu.",
  ui_story_5085_50850100_60_dialog_content = "Dari yang saya dengar, cuaca ekstrem saja telah mengalahkan banyak tim penjelajah. Saya khawatir untukmu.",
  ui_story_5085_50850100_61_dialog_content = "Kurasa kita akan baik-baik saja...",
  ui_story_5085_50850100_62_dialog_content = "Lautan ini telah tenang sepanjang waktu...",
  ui_story_5085_50850100_63_dialog_content = "Apa ini?! Petir... di hari yang cerah?!",
  ui_story_5085_50850100_64_dialog_content = "Ahhhh—Hujan api! Berlindung, semuanya!",
  ui_story_5085_50850100_65_dialog_content = "K-Kapal ini tidak akan terbalik, bukan?!",
  ui_story_5085_50850100_66_dialog_content = "Berpegangan, semuanya!",
  ui_story_5085_50850100_67_dialog_content = "<size=50><color=#e8d9bb>Duar—!</color></size>",
  ui_story_5085_50850100_68_dialog_content = "<color=#e8d9bb>Kapal itu hancur berkeping-keping, dan awak kapal dengan putus asa berpegangan pada puing-puingnya, terombang-ambing oleh ombak yang tak kenal ampun.</color>",
  ui_story_5085_50850100_69_dialog_content = "<color=#e8d9bb>Terombang-ambing di arus, aku menemukan diriku di sini sebelum aku menyadarinya...</color>",
  ui_story_5085_50850100_70_dialog_content = "Jadi... Aku juga tidak terlalu mengenal tempat ini. Maaf.",
  ui_story_5085_50850100_71_dialog_content = "Saya juga tidak sepenuhnya yakin bisa membantu Anda dengan cara apa pun...",
  ui_story_5085_50850100_72_dialog_content = "Saya mengerti. Itu tidak apa-apa!",
  ui_story_5085_50850100_73_dialog_content = "Terima kasih untuk intelnya! Sekarang saya merasa seperti saya sudah cukup memahami situasi ini.",
  ui_story_5085_50850100_74_dialog_content = "Ketika berbicara tentang tempat-tempat seperti pulau dan reruntuhan, saya memiliki banyak pengalaman!",
  ui_story_5085_50850100_75_dialog_content = "Syukurlah! Sebelum kita datang ke sini, saya sudah memiliki gambaran yang baik tentang apa yang akan terjadi.",
  ui_story_5085_50850100_76_dialog_content = "Hanya bertanya-tanya di mana yang lain berakhir. Mereka pasti juga terdampar di pantai, bukan?",
  ui_story_5085_50850100_77_dialog_content = "Temanmu... Oh, itu mengingatkan saya!",
  ui_story_5085_50850100_78_dialog_content = "Klaudia dan Patty juga dikirim ke dunia ini, tapi saya belum bisa menemukan mereka berdua...",
  ui_story_5085_50850100_79_dialog_content = "Tapi sesuatu memberitahu saya bahwa mereka pasti ada di pulau ini!",
  ui_story_5085_50850100_80_dialog_content = "Dan jika kamu memaafkan ungkapan ini, sepertinya kita berada di kapal yang sama di sini.",
  ui_story_5085_50850100_81_dialog_content = "Haha, kamu bisa mengatakan itu lagi...",
  ui_story_5085_50850100_82_dialog_content = "Dan karena itulah... Mengapa kita tidak mencoba mencari teman kita bersama-sama?",
  ui_story_5085_50850100_83_dialog_content = "Kita akan jauh lebih efektif jika kita bekerja sebagai tim!",
  ui_story_5085_50850100_84_dialog_content = "Benarkah?! Oh, terima kasih banyak atas bantuanmu! Tahu tidak, kamu tampak cukup khawatir tentang teman-temanmu juga. Kamu terus memanggil \"Vice\" ketika kamu tidak sadar sebelumnya...",
  ui_story_5085_50850100_85_dialog_content = "Dia pasti teman terdekatmu, ya?",
  ui_story_5085_50850100_86_dialog_content = "I-Itukah yang kamu pikirkan?!",
  ui_story_5085_50850100_87_dialog_content = "... Mungkin kamu benar. Datang ke sini adalah ide dia, dan aku bahkan tidak ragu untuk bergabung dengannya.",
  ui_story_5085_50850100_88_dialog_content = "Oh, aku mengerti! Dia pasti suka bertualang. Aku semakin bersemangat untuk bertemu dengannya sekarang!",
  ui_story_5085_50850100_89_dialog_content = "Bisakah kamu berjalan? Kamu bisa bersandar padaku jika terluka.",
  ui_story_5085_50850100_90_dialog_content = "Terima kasih, tapi saya pikir saya bisa mengatur.",
  ui_story_5085_50850100_91_dialog_content = "Bagus! Lalu, izinkan saya untuk memperkenalkan diri secara resmi—",
  ui_story_5085_50850100_92_dialog_content = "Namaku Reisalin Stout, tapi kamu bisa memanggilku Ryza!",
  ui_story_5085_50850100_93_dialog_content = "Senang bertemu denganmu, Ryza. Namaku PlayerName, tapi kebanyakan orang hanya memanggilku Navigator.",
  ui_story_5085_50850100_94_dialog_content = "Terlihat bagus! Tak sabar untuk bekerja denganmu, Navigator!",
  ui_story_5085_50850100_95_dialog_content = "Sekarang ayo pergi!",
  ui_story_5085_50850201_1_dialog_content = "Fiuh... Ini tampak cukup berguna.",
  ui_story_5085_50850201_2_dialog_content = "Wow, bunga ini indah! Saya bertanya-tanya apakah saya bisa menggunakannya sebagai pengganti Bunga Kesehatan.",
  ui_story_5085_50850201_3_dialog_content = "Pikirkan batu ini memiliki kegunaan apa saja? Aku harus membawanya, hanya untuk berjaga-jaga...",
  ui_story_5085_50850201_4_dialog_content = "Uh, sepertinya tas mu sudah cukup penuh.",
  ui_story_5085_50850201_5_dialog_content = "Ah! Kamu benar, aku pasti sedikit terbawa suasana dalam pengumpulanku...",
  ui_story_5085_50850201_6_dialog_content = "Sepertinya kamu cukup menyukai tanaman, terutama... akar rumput?",
  ui_story_5085_50850201_7_dialog_content = "Eheheh... Tidak tepatnya. Saya hanya ingin mencoba menggunakan ini sebagai bahan <color=#FFB400>alchemy</color>!",
  ui_story_5085_50850201_8_dialog_content = "A-Alkimia?!",
  ui_story_5085_50850201_9_dialog_content = "Hah? Apakah alkimia tidak ada di dunia ini atau bagaimana?",
  ui_story_5085_50850201_10_dialog_content = "Emmm, sejauh ini menyangkut dunia, ini lebih merupakan seni yang hilang dari masa kuno.",
  ui_story_5085_50850201_11_dialog_content = "Jadi, itu benar-benar ada di dunia Anda?",
  ui_story_5085_50850201_12_dialog_content = "Benar sekali! Dan jangan meremehkan aku, aku sebenarnya adalah <color=#FFB400>ahli kimia</color> yang cukup berprestasi.",
  ui_story_5085_50850201_13_dialog_content = "Saya bisa menggunakan berbagai jenis objek biasa sebagai bahan dan <color=#FFB400>mensintesis</color> mereka menjadi obat dan barang-barang berguna lainnya!",
  ui_story_5085_50850201_14_dialog_content = "Benarkah? Itu mengesankan!",
  ui_story_5085_50850201_15_dialog_content = "Jika saja saya memiliki kuali alkimia yang bagus dan besar... Maka saya bisa menunjukkan apa yang benar-benar bisa saya lakukan!",
  ui_story_5085_50850201_16_dialog_content = "Kuali, huh? Aku tidak yakin kita akan menemukan sesuatu seperti itu di pulau terpencil... Tapi mungkin reruntuhan memiliki sesuatu yang bisa kamu gunakan?",
  ui_story_5085_50850201_17_dialog_content = "Dalam hal apapun, mari kita terus bergerak. Kita bahkan mungkin menemukan hal-hal yang lebih baik di depan.",
  ui_story_5085_50850201_18_dialog_content = "Sekarang kamu berbicara dalam bahasaku!",
  ui_story_5085_50850201_19_dialog_content = "Biarkan aku meringankan bebanku sedikit dulu.",
  ui_story_5085_50850201_20_dialog_content = "Aku bisa membantu kamu membawa beberapa barang juga. Lagipula, aku ragu kita akan meninggalkan pulau ini dalam waktu dekat.",
  ui_story_5085_50850201_21_dialog_content = "Jika kita akan terjebak di sini selama beberapa hari, saya yakin alkimiamu pasti akan sangat berguna!",
  ui_story_5085_50850201_22_dialog_content = "Benar juga!",
  ui_story_5085_50850201_23_dialog_content = "Kemudian kita akan mulai dengan mencari teman-teman kita, lalu kita akan mencari kuali...",
  ui_story_5085_50850201_24_dialog_content = "Graah—",
  ui_story_5085_50850201_25_dialog_content = "Ah! I-Itu monster!",
  ui_story_5085_50850201_26_dialog_content = "Apakah semua monster di dunia Anda terlihat menakutkan seperti ini?!",
  ui_story_5085_50850201_27_dialog_content = "Ada Eclipsites bahkan di pulau terpencil seperti ini?!",
  ui_story_5085_50850201_28_dialog_content = "Ini buruk... tanpa Aurorian di sekitar...",
  ui_story_5085_50850201_29_dialog_content = "Eclipsite? Apakah itu yang kamu sebut dengan benda-benda ini?",
  ui_story_5085_50850201_30_dialog_content = "Yang itu sepertinya membawa sesuatu di cakarnya...",
  ui_story_5085_50850201_31_dialog_content = "Tunggu sebentar, bukankah itu...",
  ui_story_5085_50850201_32_dialog_content = "Vice's pack?!",
  ui_story_5085_50850201_33_dialog_content = "<color=#e8d9bb>Mendera!</color>",
  ui_story_5085_50850201_34_dialog_content = "Kamu Eclipsite busuk! Kembalikan milikku... Ah! PlayerName!",
  ui_story_5085_50850201_35_dialog_content = "Waktu yang sempurna! Pasokan kita masih ada di tas itu! Kita akan berada dalam masalah jika kita tidak membawanya kembali!",
  ui_story_5085_50850201_36_dialog_content = "Bantu saya!",
  ui_story_5085_50850201_37_dialog_content = "Baik!",
  ui_story_5085_50850202_1_dialog_content = "Fiuh, itu menyelesaikan masalah itu!",
  ui_story_5085_50850202_2_dialog_content = "Kami harus bertahan hidup seperti manusia gua tanpa persediaan ini.",
  ui_story_5085_50850202_3_dialog_content = "Saya sangat senang menemukanmu, PlayerName! Tapi uh, siapa ini...?",
  ui_story_5085_50850202_4_dialog_content = "Ah, kamu pasti Vice! Navigator memberitahuku tentangmu saat kita pertama kali bertemu. Namaku adalah Ryza!",
  ui_story_5085_50850202_5_dialog_content = "Eh—Ya, namaku Vice; senang bertemu denganmu, Nona Ryza! Um... Apakah kamu juga seorang petualang yang menjelajahi pulau ini?",
  ui_story_5085_50850202_6_dialog_content = "Jenisnya... Lebih spesifik, dia adalah seorang alkemis yang datang ke sini dari dunia lain.",
  ui_story_5085_50850202_7_dialog_content = "Seorang alkemis... dari dunia lain?",
  ui_story_5085_50850202_8_option_content = "Jelaskan situasi tersebut kepada Vice",
  ui_story_5085_50850202_9_dialog_content = "<color=#e8d9bb>Saya memberi Vice gambaran singkat tentang bagaimana Ryza dan saya bertemu.</color>",
  ui_story_5085_50850202_10_dialog_content = "Jadi itulah yang terjadi, huh?",
  ui_story_5085_50850202_11_dialog_content = "Ya! Dia terus memanggil namamu bahkan ketika dia masih tidak sadar juga!",
  ui_story_5085_50850202_12_dialog_content = "Oh, begitu…",
  ui_story_5085_50850202_13_dialog_content = "E-Ehem... Saya rasa kita harus beralih ke hal yang lebih penting, seperti situasi kita saat ini.",
  ui_story_5085_50850202_14_dialog_content = "Aku setuju.",
  ui_story_5085_50850202_15_dialog_content = "Ketika saya mengejar Eclipsite itu, saya menyadari ada lebih banyak Eclipsite di pulau ini daripada yang saya kira.",
  ui_story_5085_50850202_16_dialog_content = "Sumber daya juga sangat langka. Jika kita tidak dapat menemukan cara untuk mengisi ulang persediaan kita...",
  ui_story_5085_50850202_17_dialog_content = "Tunggu sebentar, Vice! Kamu terluka, bukan?",
  ui_story_5085_50850202_18_dialog_content = "Jika kamu tidak keberatan, coba oleskan obat ini ke lukamu. Aku membuatnya dengan alkimia.",
  ui_story_5085_50850202_19_dialog_content = "Hah? Tak apa, ini hanya goresan... Aku lebih baik tidak membuang-buang obat berhargamu untuk hal seperti ini...",
  ui_story_5085_50850202_20_dialog_content = "Tidak apa-apa, sungguh—",
  ui_story_5085_50850202_21_dialog_content = "<color=#e8d9bb>Ryza dengan lembut mengoleskan obatnya ke luka Vice—</color>",
  ui_story_5085_50850202_22_dialog_content = "Nng... Hah?!",
  ui_story_5085_50850202_23_dialog_content = "Ini benar-benar sembuh... Apakah ini kekuatan alkemimu, Ryza?",
  ui_story_5085_50850202_24_dialog_content = "Kamu harus bisa melakukan apa saja dengannya!",
  ui_story_5085_50850202_25_dialog_content = "Benar sekali! Alkimia bisa menyelesaikan hampir semua masalah! Atau setidaknya aku suka berpikir begitu... Tapi yang pasti, itu akan membuat hidup di pulau terpencil ini jauh lebih mudah! Bahkan mungkin berguna melawan Eclipsite!",
  ui_story_5085_50850202_26_dialog_content = "Saya yakin bisa! Aku percaya pada kekuatanmu.",
  ui_story_5085_50850202_27_dialog_content = "Aku yakin Vice juga melihatnya! Kamu akan menjadi teman tim yang sempurna untuk menjelajahi reruntuhan kuno dan wilayah rahasia.",
  ui_story_5085_50850202_28_dialog_content = "Saya setuju! Tidak ada yang lebih baik daripada bertemu dengan sekutu yang kuat seperti kamu.",
  ui_story_5085_50850202_29_dialog_content = "Haha, sepertinya aku juga harus bekerja keras demi kepentingan semua orang! Dan aku akan mulai dengan mencari kuali.",
  ui_story_5085_50850202_30_dialog_content = "Sebuah kuali?",
  ui_story_5085_50850202_31_dialog_content = "Ini adalah apa yang Ryza butuhkan untuk melakukan alkimia dan menciptakan berbagai jenis barang. Apapun yang menyerupai pot akan cukup.",
  ui_story_5085_50850202_32_dialog_content = "Ah, mengerti.",
  ui_story_5085_50850202_33_dialog_content = "Saya melihat sesuatu seperti itu di perjalanan ke sini. Sepertinya semacam bejana upacara di reruntuhan...",
  ui_story_5085_50850202_34_dialog_content = "<color=#e8d9bb>Suara seruling tiba-tiba datang dari jauh di dalam hutan—</color>",
  ui_story_5085_50850202_35_dialog_content = "Saya rasa ada seseorang di hutan!",
  ui_story_5085_50850202_36_dialog_content = "Instrumen itu... Itu pasti Klaudia!",
  ui_story_5085_50850202_37_dialog_content = "Tolong ikut denganku! Dia adalah teman yang paling bisa dipercaya... Serta sahabatku terbaik!",
  ui_story_5085_50850301_1_dialog_content = "Datanglah, teman saya dari negeri yang jauh! Mari kita kalahkan Eclipsites yang ada di tangan kita!♪",
  ui_story_5085_50850301_2_dialog_content = "Ah, itu PlayerName!",
  ui_story_5085_50850301_3_dialog_content = "Syukurlah, kau masih hidup!",
  ui_story_5085_50850301_4_dialog_content = "Maaf, tapi saya tidak turun semudah itu!",
  ui_story_5085_50850301_5_dialog_content = "Klaudia!",
  ui_story_5085_50850301_6_dialog_content = "Ah, Ryza!",
  ui_story_5085_50850301_7_dialog_content = "Syukurlah... Ketika setiap orang terpisah di portal, aku tidak tahu harus berbuat apa...",
  ui_story_5085_50850301_8_dialog_content = "Maaf telah membuatmu khawatir, Klaudia.",
  ui_story_5085_50850301_9_dialog_content = "Tapi jika aku bisa menemukanmu di sini, itu berarti Patty kemungkinan besar juga ada di suatu tempat di pulau ini.",
  ui_story_5085_50850301_10_dialog_content = "Ya, saya juga berpikir begitu.",
  ui_story_5085_50850301_11_dialog_content = "Aku tahu kamu akan menemukanku pada akhirnya, jadi aku memutuskan untuk tinggal di sini dan menjaga ini untukmu, Ryza.",
  ui_story_5085_50850301_12_dialog_content = "Itu…",
  ui_story_5085_50850301_13_dialog_content = "Sebuah tong!",
  ui_story_5085_50850301_14_dialog_content = "Uh, tidak... Maksudku benda di sebelahnya.",
  ui_story_5085_50850301_15_dialog_content = "Oh! Ini... Ini adalah kuali besar yang indah! Terima kasih banyak, Klaudia!",
  ui_story_5085_50850301_16_dialog_content = "Tampaknya ini adalah peninggalan dari peradaban kuno, tetapi ukuran dan bentuknya sangat cocok untuk alkimia.",
  ui_story_5085_50850301_17_dialog_content = "Ini adalah kapal tiga kaki yang saya lihat sebelumnya! Reruntuhan pasti ada di sekitar sini di suatu tempat.",
  ui_story_5085_50850301_18_dialog_content = "Ah, saya lupa untuk memperkenalkan diri kami! Nama saya Vice, dan ini adalah PlayerName, Navigator kami.",
  ui_story_5085_50850301_X18_dialog_content = "Senang bertemu denganmu, Nona Vice dan Tuan Navigator. Nona Barbara sebenarnya sudah memberitahuku tentangmu dalam perjalanan; Saya harap kita bisa menjadi teman yang baik!",
  ui_story_5085_50850301_X19_dialog_content = "Saya yakin kamu bisa! Sekarang jangan sia-siakan semua kerja keras Klaudia... PlayerName, bisakah kamu menggunakan kekuatanmu untuk merasakan panci ini?",
  ui_story_5085_50850301_19_dialog_content = "Saya setuju. Kita tidak ingin ada yang terjadi pada Ryza setelah dia mulai menggunakannya.",
  ui_story_5085_50850301_20_dialog_content = "Apa itu? Navigator yang hebat dan kuat akhirnya akan menggunakan kemampuannya yang misterius?",
  ui_story_5085_50850301_21_dialog_content = "Ini bukan apa-apa, hanya persepsi ekstrasensori biasa—",
  ui_story_5085_50850301_22_option_content = "Force Boost!",
  ui_story_5085_50850301_23_dialog_content = "...",
  ui_story_5085_50850301_24_dialog_content = "Sehat?",
  ui_story_5085_50850301_25_dialog_content = "Aku melihat satu set reruntuhan... dengan banyak kapal pecah yang tergeletak di tanah...",
  ui_story_5085_50850301_26_dialog_content = "Sepertinya mereka adalah bagian dari reruntuhan setelah semua.",
  ui_story_5085_50850301_27_dialog_content = "Sebuah kerajaan pulau kecil yang dibangun berdasarkan teknologi peradaban kuno, berkembang pesat hingga...",
  ui_story_5085_50850301_28_dialog_content = "Kembalilah. Kerajaan membutuhkanmu.",
  ui_story_5085_50850301_29_dialog_content = "Ah—",
  ui_story_5085_50850301_30_dialog_content = "Apa yang terjadi?",
  ui_story_5085_50850301_31_dialog_content = "Kamu tampak seperti baru saja melihat hantu. Mau kuambilkan air minum?",
  ui_story_5085_50850301_32_dialog_content = "... Tidak ada apa-apa. Saya baru saja melihat sejarah reruntuhan, dan ada banyak hal yang harus dipahami dalam satu waktu...",
  ui_story_5085_50850301_33_dialog_content = "Bagaimanapun, tidak ada kontaminasi Darkflow pada kapal, dan Eclipsite bahkan tidak menyentuhnya sama sekali. Seharusnya aman untuk digunakan.",
  ui_story_5085_50850301_34_dialog_content = "Benarkah? Bagus, terima kasih banyak! Tapi tetap saja, saya harap kamu tidak berlebihan dalam ini.",
  ui_story_5085_50850301_35_dialog_content = "Saya baik-baik saja, jujur. Lagipula, saya sangat menantikan bagaimana kekuatanmu akan memperbaiki kehidupan pulau terpencil kita!",
  ui_story_5085_50850301_36_dialog_content = "Tidak perlu khawatir tentang itu! Dengan aku di sini, bertahan hidup akan menjadi jauh lebih mudah!",
  ui_story_5085_50850301_37_dialog_content = "Tapi... Masih ada rintangan besar untuk bertahan hidup kita yang mengintai di sekitar...",
  ui_story_5085_50850301_38_dialog_content = "Makhluk jahat itu semakin gelisah. Jika bukan karena keterampilan bertarung yang luar biasa dari Miss Barbara tadi...",
  ui_story_5085_50850301_39_dialog_content = "Oh tidak, aku tidak SEKUAT itu, tahu.",
  ui_story_5085_50850301_40_dialog_content = "Dukunganmu adalah satu-satunya alasan pertempuran kita berjalan begitu lancar, temanku!",
  ui_story_5085_50850301_41_dialog_content = "Dan seruling itu... Sangat memikat, bahkan untuk seorang idola profesional seperti saya!",
  ui_story_5085_50850301_42_dialog_content = "Kita perlu mengambil beberapa tindakan pencegahan terhadap Eclipsite. Kita harus mendirikan kamp di tempat yang mudah dipertahankan.",
  ui_story_5085_50850301_43_dialog_content = "Dunia milikmu ini... Apakah ada barang atau bahan untuk mengusir monster? Maksud saya, Eclipsite?",
  ui_story_5085_50850301_44_dialog_content = "Meragukannya. Berharap ada sesuatu yang semudah itu di sini.",
  ui_story_5085_50850301_45_dialog_content = "Um…",
  ui_story_5085_50850301_46_dialog_content = "Ada apa, Klaudia?",
  ui_story_5085_50850301_47_dialog_content = "Ryza, menurutmu... Apakah kita akan bisa pulang?",
  ui_story_5085_50850301_48_dialog_content = "Tentu. Kita selalu berhasil kembali dari petualangan kita, bukan?",
  ui_story_5085_50850301_50_dialog_content = "Aku tahu kita sudah menghadapi beberapa masalah, tapi sekarang aku hanya ingin menikmati petualangan bersama setiap orang di sini!",
  ui_story_5085_50850301_51_dialog_content = "Setuju! Tidak ada yang lebih menyenangkan daripada berpetualang bersamamu, Ryza!",
  ui_story_5085_50850301_53_dialog_content = "Hihihi, terima kasih! Nah, demi menemukan jalan pulang dengan selamat, mari bergabung dengan Navigator dan teman-temannya dan mencari Patty!",
  ui_story_5085_50850301_58_dialog_content = "Tunggu sebentar! Kurasa aku mendengar sesuatu yang mengerikan...",
  ui_story_5085_50850301_59_dialog_content = "Eclipsites! Dan mereka semakin dekat!",
  ui_story_5085_50850301_60_dialog_content = "Graah—",
  ui_story_5085_50850301_61_dialog_content = "Ryza, awas!",
  ui_story_5085_50850301_62_dialog_content = "Wow... Pertempuran lagi?!",
  ui_story_5085_50850302_1_dialog_content = "Lihatlah kekuatan alkimia!",
  ui_story_5085_50850302_2_dialog_content = "Graah...",
  ui_story_5085_50850302_3_dialog_content = "Fiuh... Hampir saja! Untung aku punya cukup bahan!",
  ui_story_5085_50850302_4_dialog_content = "Hei Ryza, apakah kamu membuat itu menggunakan alkimia?",
  ui_story_5085_50850302_5_dialog_content = "Benar! Cukup mengesankan, ya?",
  ui_story_5085_50850302_6_dialog_content = "Itu adalah pernyataan yang meremehkan, setidaknya. Dengan kekuatan seperti ini, menjelajahi pulau seharusnya bukan tantangan.",
  ui_story_5085_50850302_7_dialog_content = "Namun, itu hanya menyelesaikan masalah pertempuran kita. Miss Vice benar: kita perlu mencari tempat yang cocok untuk mendirikan kamp dasar kita.",
  ui_story_5085_50850302_8_dialog_content = "Ya, kamu benar. Dengan banyaknya Eclipsites yang berkeliaran, tempat yang aman untuk merencanakan strategi akan sangat membantu.",
  ui_story_5085_50850302_9_dialog_content = "Jadi, apakah ada yang punya saran untuk kamp kita?",
  ui_story_5085_50850302_10_dialog_content = "Saya pikir... Di dekat pantai mungkin yang terbaik.",
  ui_story_5085_50850302_11_dialog_content = "Dari apa yang saya dan Miss Barbara lihat sebelumnya, sebagian besar pulau ini tampaknya dipenuhi dengan puing-puing reruntuhan kuno yang hancur.",
  ui_story_5085_50850302_12_dialog_content = "Hal yang sama mungkin juga berlaku untuk Eclipsites...",
  ui_story_5085_50850302_13_dialog_content = "Namun, pantai tampaknya sebagian besar bersih dari sisa-sisa ini, yang mungkin berarti mereka adalah pilihan teraman kita. Tidak hanya itu, kita juga bisa mengawasi kapal yang lewat.",
  ui_story_5085_50850302_14_dialog_content = "Aku baru saja berpikir hal yang sama persis!",
  ui_story_5085_50850302_15_dialog_content = "Sepertinya Anda memiliki mata yang tajam untuk strategi.",
  ui_story_5085_50850302_16_dialog_content = "Anda dan Ryza sangat berbeda... Itulah mengapa kalian saling melengkapi dengan baik!",
  ui_story_5085_50850302_17_dialog_content = "Sebenarnya, selama ini Ryza selalu mengawasiku.",
  ui_story_5085_50850302_18_dialog_content = "Apa yang kamu bicarakan? Kamu lah yang selalu menjagaku.",
  ui_story_5085_50850302_19_dialog_content = "Ya, ya, kami mengerti bahwa kalian berdua sangat akrab! Sekarang mari kita lanjutkan ke tujuan berikutnya!",
  ui_story_5085_50850302_20_dialog_content = "Dan itu adalah—Membangun panggung yang indah untuk mengekspresikan perasaan persahabatan kita!",
  ui_story_5085_50850302_21_dialog_content = "Er, saya pikir dia maksud mencari pantai yang cocok untuk kamp kita.",
  ui_story_5085_50850302_22_dialog_content = "Apa yang kamu lakukan, Klaudia? Apakah kamu menjatuhkan sesuatu?",
  ui_story_5085_50850302_23_dialog_content = "Ah, saya baru saja mencari sisa-sisa yang saya sebutkan sebelumnya. Sepertinya ada beberapa di antaranya yang berserakan di sekitar sini...",
  ui_story_5085_50850302_24_dialog_content = "Setiap kali Ryza membawa kita berpetualang, kita cenderung mengambil barang-barang yang tampaknya tidak berguna seperti ini.",
  ui_story_5085_50850302_25_dialog_content = "Kamu tidak pernah tahu... Beberapa di antaranya mungkin adalah bahan alkimia yang kuat.",
  ui_story_5085_50850302_26_dialog_content = "Saya mengerti. Mungkin saya bisa menggunakan kekuatan saya untuk mencari sesuatu yang berguna juga!",
  ui_story_5085_50850302_27_dialog_content = "Itu terdengar sangat seperti perburuan harta karun! Sebagai penduduk asli Gurun Rediesel, itu adalah salah satu keahlian saya!",
  ui_story_5085_50850302_28_dialog_content = "Hmm... Ini tampaknya mainan seorang bangsawan kuno... Membosankan!",
  ui_story_5085_50850302_29_dialog_content = "Hahaha! Saya rasa saya harus menyebutkan bahwa orang-orang dari Gurun Rediesel tidak terlalu peduli pada apa pun yang tidak bisa dipasang pada mesin besar.",
  ui_story_5085_50850302_30_dialog_content = "Berbicara tentang mesin raksasa... Ada seseorang yang mencari informasi tentang mecha kuno di pulau ini.",
  ui_story_5085_50850302_31_dialog_content = "Aneh... entah kenapa, aku tidak bisa mengingat siapa orangnya.",
  ui_story_5085_50850302_32_dialog_content = "Apa jenis hal yang kamu bicarakan? Bisakah saya menggunakan alkimia padanya?",
  ui_story_5085_50850302_33_dialog_content = "Ryza, perhatikan langkahmu!",
  ui_story_5085_50850302_34_dialog_content = "... Wah!",
  ui_story_5085_50850302_35_dialog_content = "Hampir saja... Bagaimana bisa ada es di sini?!",
  ui_story_5085_50850302_36_dialog_content = "Hei... Jika kamu melihatnya lebih dekat, es ini tampak aneh berbentuk seperti panah...",
  ui_story_5085_50850302_37_dialog_content = "Es berbentuk panah? Tunggu... Bisa jadi?!",
  ui_story_5085_50850302_38_dialog_content = "Ini pasti gara-gara Zarya!",
  ui_story_5085_50850302_39_dialog_content = "Sepertinya dia meninggalkan jejak... Saya yakin kita akan menemukannya jika kita mengikutinya.",
  ui_story_5085_50850302_40_dialog_content = "Jadi, teman Navigator meninggalkan tanda untuk kita!",
  ui_story_5085_50850302_41_dialog_content = "Saya bertanya-tanya apakah Patty melakukan hal yang sama di tempat lain?",
  ui_story_5085_50850401_1_dialog_content = "Para Eclipsite telah diberantas. Tolong tinggalkan tanda lain di sini, Nona Zarya.",
  ui_story_5085_50850401_2_dialog_content = "Eh... Oke!",
  ui_story_5085_50850401_3_dialog_content = "Ada masalah? Anda tampaknya sibuk.",
  ui_story_5085_50850401_4_dialog_content = "Tidak, hanya saja... Kamu jauh lebih dewasa daripada yang tampak, Lady Patricia.",
  ui_story_5085_50850401_5_dialog_content = "Meskipun kamu tidak sepenuhnya menyetujui rencanaku, kamu telah membantuku membasmi Eclipsite dan meninggalkan tanda untuk yang lain...",
  ui_story_5085_50850401_6_dialog_content = "<size=30>Andai saja aku bisa sedikit lebih dewasa juga...</size>",
  ui_story_5085_50850401_7_dialog_content = "Sejujurnya, aku sudah memberitahumu—",
  ui_story_5085_50850401_8_dialog_content = "Ini tidak ada hubungannya dengan kedewasaan. Seorang bangsawan tidak mudah mengingkari kata-katanya, terutama ketika dia telah setuju untuk melakukan sesuatu.",
  ui_story_5085_50850401_9_dialog_content = "Juga, Anda tidak perlu memanggil saya seperti itu. Anda bisa hanya...",
  ui_story_5085_50850401_10_dialog_content = "Kau…",
  ui_story_5085_50850401_11_dialog_content = "Zarya—Di sini—",
  ui_story_5085_50850401_12_dialog_content = "Ini PlayerName!",
  ui_story_5085_50850401_13_dialog_content = "Jika ada yang menemukan kita, berarti...",
  ui_story_5085_50850401_14_dialog_content = "Penanda es... Berhasil!",
  ui_story_5085_50850401_15_dialog_content = "Patty! Akhirnya kami menemukanmu!",
  ui_story_5085_50850401_16_dialog_content = "Ryza?! Oh...",
  ui_story_5085_50850401_17_dialog_content = "Aku punya firasat kamu juga ada di pulau ini! Ini sungguh reuni yang gila, 'kan?",
  ui_story_5085_50850401_18_dialog_content = "Syukurlah kau selamat, Patricia.",
  ui_story_5085_50850401_19_dialog_content = "Aku hanya senang kita semua menemukan satu sama lain... Jadi, bolehkah aku bertanya siapa teman-temanmu?",
  ui_story_5085_50850401_20_dialog_content = "<color=#e8d9bb>Setelah bertukar perkenalan singkat, Patricia menjelaskan situasi sebelumnya.</color>",
  ui_story_5085_50850401_21_dialog_content = "Begitu ya. Jadi kamu telah bekerja dengan Navigator ini sejak kita dipindahkan ke dunia ini.",
  ui_story_5085_50850401_22_dialog_content = "Kamu selalu tampak menarik pencari petualangan lain di mana pun kamu pergi, Ryza. Sungguh luar biasa.",
  ui_story_5085_50850401_23_dialog_content = "Bukan hanya aku, tahu. Teman-teman kita di sini kebetulan memiliki tujuan yang serupa dengan kita!",
  ui_story_5085_50850401_24_dialog_content = "Saya mengerti sekarang. Izinkan saya memperkenalkan diri sekali lagi: Saya Patricia Abelheim, tetapi kamu boleh memanggil saya Patty untuk pendek. Saya merasa terhormat bertemu dengan kalian semua.",
  ui_story_5085_50850401_25_dialog_content = "Wow, apa sebuah perkenalan... Dia terdengar seperti seorang ksatria!",
  ui_story_5085_50850401_26_dialog_content = "Itu karena Patty adalah seorang bangsawan!",
  ui_story_5085_50850401_27_dialog_content = "Saya mengerti, itu menjelaskan mengapa dia mengingatkan saya pada seorang teman tertentu! Dia juga seorang bangsawan yang bermartabat, serta seorang ksatria yang hebat!",
  ui_story_5085_50850401_28_dialog_content = "Dan dengan itu, semua teman saya telah terhitung! Bagaimana dengan kamu, Navigator?",
  ui_story_5085_50850401_29_dialog_content = "Begini...",
  ui_story_5085_50850401_30_dialog_content = "Dengan ditemukannya Zarya, pestanya seharusnya juga sudah lengkap sekarang.",
  ui_story_5085_50850401_31_dialog_content = "Hmm... Mungkin kita harus menghitung jumlah orang satu kali lagi, hanya untuk memastikan?",
  ui_story_5085_50850401_32_dialog_content = "Satu, dua, tiga, empat! Ya, kita semua di sini!",
  ui_story_5085_50850401_33_dialog_content = "Hanya empat? Saya merasa seperti kita kehilangan seseorang...",
  ui_story_5085_50850401_34_dialog_content = "Mungkin kamu hanya memikirkan Corax? Dia bilang dia juga ingin datang, ingat?",
  ui_story_5085_50850401_35_dialog_content = "Kamu benar... Mungkin aku terlalu memikirkan banyak hal.",
  ui_story_5085_50850401_36_dialog_content = "Saya rasa kita sudah bagus sekarang, Ryza. Apa langkahmu selanjutnya?",
  ui_story_5085_50850401_37_dialog_content = "Pertama, saya perlu mengambil kuali itu dan membawanya ke pantai yang cocok. Setelah itu, saya bisa membuat atelier untuk kita gunakan!",
  ui_story_5085_50850401_38_dialog_content = "Setelah kita memiliki itu, kita akan beristirahat, membuat banyak barang berguna, dan melanjutkan penjelajahan kita di reruntuhan!",
  ui_story_5085_50850401_39_dialog_content = "Apa yang dipikirkan semua orang tentang rencana sejauh ini?",
  ui_story_5085_50850401_40_dialog_content = "Meski kita berada di dunia yang sama sekali tidak dikenal... Ryza tetap bersemangat seperti biasanya.",
  ui_story_5085_50850401_41_dialog_content = "Tidak ada keberatan di sini. Saya percaya sebuah Atelier akan sangat penting untuk menemukan jalan pulang kita.",
  ui_story_5085_50850401_42_dialog_content = "Setuju. Reruntuhan pulau yang terkait dengan musik kuno juga layak untuk diselidiki.",
  ui_story_5085_50850401_43_dialog_content = "Saya percaya rencana Ryza adalah rencana yang bagus.",
  ui_story_5085_50850401_44_dialog_content = "Seperti halnya saya.",
  ui_story_5085_50850401_45_dialog_content = "Hebat! Aku juga ingin terus membara api petualangan musim panas kita! Bagaimana denganmu, Navigator?",
  ui_story_5085_50850401_46_dialog_content = "Kami juga datang untuk menjelajahi reruntuhan itu.",
  ui_story_5085_50850401_47_dialog_content = "Tapi masih ada pertanyaan tentang bagaimana kita akan kembali ke daratan utama...",
  ui_story_5085_50850401_48_dialog_content = "Dalam kasus apapun, kita tidak bisa kembali sekarang!",
  ui_story_5085_50850401_49_dialog_content = "Jika kita pulang dengan tangan kosong, kita akan kehilangan pembayaran DAN kita harus membayar untuk kapal... Ugh, jika saya tahu sesuatu seperti ini akan terjadi, saya sudah membeli asuransi bencana di Umbraton...",
  ui_story_5085_50850401_50_dialog_content = "Selain itu, mungkin kita akan menemukan kapal atau semacam perangkat komunikasi di reruntuhan?",
  ui_story_5085_50850401_51_dialog_content = "... Kau benar. Saya tidak bisa memikirkan solusi yang lebih baik sekarang juga...",
  ui_story_5085_50850401_52_dialog_content = "Dalam hal ini, mari bergabung dalam penjelajahan dan selesaikan misi kita!",
  ui_story_5085_50850401_53_dialog_content = "Wow, sepertinya semangat semua orang tinggi! Nah, sekarang... Kita berangkat ke pantai—",
  ui_story_5085_50850401_54_dialog_content = "Ayo pergi!",
  ui_story_5085_50850501_1_dialog_content = "Ha—Fiuh—!",
  ui_story_5085_50850501_2_dialog_content = "Tempat ini seharusnya baik-baik saja! Terima kasih lagi, semuanya!",
  ui_story_5085_50850501_3_dialog_content = "Aku bahkan tidak pernah mempertimbangkan menggunakan es dari Zarya seperti ini. Kita benar-benar mengangkut kuali sejauh ini dengan bantuan es...",
  ui_story_5085_50850501_4_dialog_content = "I-Ini bukan apa-apa, sungguh. Kekuatanku tak begitu berguna selain untuk ini...",
  ui_story_5085_50850501_5_dialog_content = "Rasanya semua akan berjalan baik-baik saja begitu Ryza bisa melakukan alkimianya.",
  ui_story_5085_50850501_6_dialog_content = "Heheh, benar sekali. Alkimia Ryza itu sungguh luar biasa.",
  ui_story_5085_50850501_7_dialog_content = "Untuk lokasi yang cocok untuk atelier, lihat tempat ini, Ryza—",
  ui_story_5085_50850501_8_dialog_content = "Bagian hutan ini menyediakan banyak sinar matahari dan air bersih yang mudah didapatkan. Ini adalah tempat yang layak untuk mendirikan tempat berlindung.",
  ui_story_5085_50850501_9_dialog_content = "Pantai juga berada di dekat sana, yang memungkinkan kita untuk melihat laut kapan saja.",
  ui_story_5085_50850501_11_dialog_content = "Kenapa tidak! Saya yakin setiap orang akan menghargai sebuah pondok tepi pantai yang indah di hutan!",
  ui_story_5085_50850501_12_dialog_content = "Saya siap untuk mulai mensintesis semua yang kita butuhkan untuk membangun pondok kita.",
  ui_story_5085_50850501_13_dialog_content = "Lalu saya akan pergi menjemput Navigator. Dia sudah lama ingin melihat alkimia Ryza.",
  ui_story_5085_50850501_14_dialog_content = "Itu—?",
  ui_story_5085_50850501_15_dialog_content = "Wow! Banyak sekali!!!",
  ui_story_5085_50850501_16_dialog_content = "Semua jenis material konstruksi, dipotong dan dibentuk sesuai spesifikasi yang tepat... Dan dia terus saja mengeluarkannya dari kuali!",
  ui_story_5085_50850501_17_dialog_content = "Yang kita lakukan hanyalah membuang banyak barang biasa secara acak...",
  ui_story_5085_50850501_18_dialog_content = "J-Jadi ini adalah kekuatan alkimia! Sangat berguna! Kamu bisa membangun seluruh rumah tanpa harus berkeringat...",
  ui_story_5085_50850501_19_dialog_content = "Jangan hanya berdiri di sana sementara Miss Ryza melakukan semua pekerjaan, setiap orang! Mari kita mulai membangun atelier itu!",
  ui_story_5085_50850501_20_dialog_content = "Saya datang!",
  ui_story_5085_50850501_21_dialog_content = "Aku bisa menangani pemindahan semua kayu, jadi serahkan saja padaku!",
  ui_story_5085_50850501_22_dialog_content = "Apakah itu baik-baik saja? Mereka sangat berat...",
  ui_story_5085_50850501_23_dialog_content = "Mungkin sebaiknya saya yang melakukannya? Meminta seorang idola yang mungil untuk mengangkut balok kayu tampak sedikit salah.",
  ui_story_5085_50850501_24_dialog_content = "Begitu? Humph! Jangan berani-berani meremehkan idola nomor satu Gurun Rediesel! Arrrrraaaaaagh—",
  ui_story_5085_50850501_25_dialog_content = "<color=#e8d9bb>Klang—Patah—Duduk—!</color>",
  ui_story_5085_50850501_26_dialog_content = "L-Luar biasa! Dia mampu membawa semua material konstruksi itu meski tubuhnya kecil...",
  ui_story_5085_50850501_27_dialog_content = "Apa yang kamu lakukan, Zarya?",
  ui_story_5085_50850501_28_dialog_content = "Aku? Eh... Aku menggunakan esku untuk membuat struktur pendukung untuk setiap orang dan mendinginkan area ini.",
  ui_story_5085_50850501_29_dialog_content = "Itu adalah ide Patty.",
  ui_story_5085_50850501_30_dialog_content = "Sulit untuk tidak terkesan setelah melihat apa yang bisa Anda lakukan, Nona Zarya.",
  ui_story_5085_50850501_31_dialog_content = "Meski <color=#FFB400>seumuran</color> denganku, kekuatanmu jauh lebih besar daripada ku... Itu benar-benar luar biasa.",
  ui_story_5085_50850501_32_dialog_content = "...",
  ui_story_5085_50850501_33_dialog_content = "Er... Apa aku mengatakan sesuatu yang salah?",
  ui_story_5085_50850501_34_dialog_content = "Entahlah, apakah kamu?",
  ui_story_5085_50850501_35_dialog_content = "Uh, mungkin karena kamu menyebutkan usianya...",
  ui_story_5085_50850501_36_dialog_content = "Usia Miss Zarya? Apakah kamu bilang pada saya... Dia dan saya sebenarnya tidak begitu dekat dalam usia?!",
  ui_story_5085_50850501_37_dialog_content = "Ya ampun...",
  ui_story_5085_50850501_39_dialog_content = "...",
  ui_story_5085_50850501_40_dialog_content = "<size=30>Saya <color=#FFB400>117</color>...</size>",
  ui_story_5085_50850501_41_dialog_content = "<size=50>?!?!</size>",
  ui_story_5085_50850501_42_dialog_content = "Dia benar-benar menemukan keberanian untuk mengatakannya!",
  ui_story_5085_50850501_X42_dialog_content = "Heheh, semoga aku tidak menakutimu.",
  ui_story_5085_50850501_X43_dialog_content = "Tidak bohong, itu sedikit mengejutkan. Tapi saat aku memikirkannya, kita juga punya teman yang tampak tidak sesuai dengan usia sebenarnya.",
  ui_story_5085_50850501_X44_dialog_content = "Itu benar.",
  ui_story_5085_50850501_X45_dialog_content = "Sekarang setelah kamu menyebutkannya, kamu benar.",
  ui_story_5085_50850501_43_dialog_content = "Ahhhh—Mari kita lupakan saja dan lanjutkan! Kita masih perlu membangun atelier ini!!!",
  ui_story_5085_50850501_44_dialog_content = "Akhirnya selesai juga, dan kuali itu tepat di tempat yang seharusnya!",
  ui_story_5085_50850501_45_dialog_content = "Nikmati satu-satunya Atelier di dunia ini, yang dibawakan khusus untukmu oleh Ryza Stout!",
  ui_story_5085_50850501_46_dialog_content = "Dan dengan pekerjaan kita akhirnya selesai...",
  ui_story_5085_50850501_47_dialog_content = "Saatnya bersenang-senang di musim panas yang sesungguhnya! Biarkan saya yang memasak; Saya ingin menunjukkan kepada semua orang bagaimana kami memanggang makanan di Gurun Rediesel!",
  ui_story_5085_50850501_48_dialog_content = "Oke, aku akan pergi menyisir pantai untuk mencari bahan dan bahan makanan apa pun.",
  ui_story_5085_50850501_49_dialog_content = "Dan aku akan... membuat beberapa makanan penutup dari bahan-bahan milik semua orang.",
  ui_story_5085_50850501_50_dialog_content = "Aku tidak ingin masuk ke dalam air, jadi aku hanya akan membantu menyiapkan makanan.",
  ui_story_5085_50850501_51_dialog_content = "Ayo, Patty! Tidak ada serunya kecuali kita semua pergi bermain di pantai bersama...",
  ui_story_5085_50850501_52_dialog_content = "Ehm... Ryza? Saya rasa kita sedang melupakan sesuatu yang sangat penting...",
  ui_story_5085_50850501_53_dialog_content = "Ketika kita datang ke dunia ini, kita tidak membawa baju renang sama sekali.",
  ui_story_5085_50850501_54_dialog_content = "Kamu benar... Kita selalu bisa mengumpulkan material untukku membuat beberapa... Tapi akan gelap saat aku selesai.",
  ui_story_5085_50850501_55_dialog_content = "Oh! Sebenarnya... Saya kebetulan membawa baju renang ekstra.",
  ui_story_5085_50850501_56_dialog_content = "B-benarkah?!",
  ui_story_5085_50850501_57_dialog_content = "Uh-huh! Saya bermaksud memberikannya kepada Carleen sebagai hadiah... Dia adalah teman dekat kami yang lain.",
  ui_story_5085_50850501_58_dialog_content = "Tapi dia selalu begitu sibuk dengan pekerjaan dan urusan resmi lainnya. Dia mungkin tidak akan mendapatkan kesempatan untuk memakainya sebelum musim panas berakhir.",
  ui_story_5085_50850501_59_dialog_content = "Jika kamu tidak keberatan, kamu sangat diperbolehkan untuk memakainya.",
  ui_story_5085_50850501_60_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian—</color>",
  ui_story_5085_50850501_61_dialog_content = "Ahh!!",
  ui_story_5085_50850501_62_dialog_content = "Ada apa?!",
  ui_story_5085_50850501_63_dialog_content = "Baju renang ini terlihat luar biasa! Terima kasih!",
  ui_story_5085_50850502_1_dialog_content = "Saatnya bermain di air!",
  ui_story_5085_50850502_2_dialog_content = "Wow, itu dingin! Kamu yakin tidak mau bergabung dengan kami, Patty?",
  ui_story_5085_50850502_3_dialog_content = "Positif. Tanpa baju renang ekstra... Aku menolak untuk mempermalukan diri di depan semua orang.",
  ui_story_5085_50850502_4_dialog_content = "Benarkah? Itu sungguh disayangkan, tapi tidak apa-apa! Mari ke sini, semua orang; inilah material yang akan kita butuhkan...",
  ui_story_5085_50850502_5_dialog_content = "<color=#e8d9bb>Percikan—</color>",
  ui_story_5085_50850502_6_dialog_content = "Wow! N-Nona Barbara?! Apa yang sedang kamu...",
  ui_story_5085_50850502_7_dialog_content = "Saya pikir kita sedang bermain, bukan? Lebih baik kita bergerak, atau aku benar-benar akan memberimu pelajaran! Hah!",
  ui_story_5085_50850502_8_dialog_content = "<color=#e8d9bb>Percikan—!</color>",
  ui_story_5085_50850502_9_dialog_content = "Heh... Dalam hal itu, aku juga tidak akan menahan diri! Hyaah!",
  ui_story_5085_50850502_10_dialog_content = "Ah! T-Tunggu sebentar, aku belum siap secara mental untuk ini...!",
  ui_story_5085_50850502_11_dialog_content = "Ini bukan waktu untuk bermain-main... Sekarang lindungi aku, PlayerName!",
  ui_story_5085_50850502_12_dialog_content = "<color=#e8d9bb>Percikan—!</color>",
  ui_story_5085_50850502_13_dialog_content = "...",
  ui_story_5085_50850502_14_dialog_content = "Jadi begitu, ya...",
  ui_story_5085_50850502_15_dialog_content = "Semoga kalian semua siap untuk kalah!!!",
  ui_story_5085_50850502_16_dialog_content = "<color=#e8d9bb>Percikan—!</color>",
  ui_story_5085_50850502_17_dialog_content = "<color=#e8d9bb>Matahari perlahan terbenam saat mereka bermain dan mengumpulkan bahan-bahan untuk barbekyu yang lezat. Saat perut mereka sudah kenyang, malam telah tiba.</color>",
  ui_story_5085_50850502_18_dialog_content = "Sangat menyenangkan bisa bersantai setelah hari yang panjang dan penuh tekanan...",
  ui_story_5085_50850502_19_dialog_content = "Saya tidak menyadari minuman saya akan begitu populer, kalau tidak saya akan membuat lebih banyak! Untungnya, pulau ini menawarkan beberapa bahan yang benar-benar segar.",
  ui_story_5085_50850502_20_dialog_content = "Tentu saja, kita harus berterima kasih kepada semua orang yang telah menjelajahi bahan-bahan tersebut, dan Miss Zarya yang telah menyediakan es!",
  ui_story_5085_50850502_21_dialog_content = "Bukan apa-apa... Kamu hanya sangat berbakat dalam membuat minuman, Nona Klaudia!",
  ui_story_5085_50850502_22_dialog_content = "Terima kasih... Meski kami...",
  ui_story_5085_50850502_23_dialog_content = "Meskipun kami menghabiskan banyak waktu bermain sampai lupa mengumpulkan lebih banyak bahan...",
  ui_story_5085_50850502_24_dialog_content = "Saya pikir kesenangan yang kita alami dan kenangan yang kita buat bahkan lebih penting!",
  ui_story_5085_50850502_25_dialog_content = "Izinkan saya untuk berterima kasih lagi kepada semua orang yang telah mencicipi calamari spesial Rediesel buatanku! Aku sudah berusaha keras dan jiwa untuk membuatnya hari ini!",
  ui_story_5085_50850502_26_dialog_content = "Meskipun sebenarnya tidak cukup untuk dibagi, dan beberapa bagian sedikit hangus...",
  ui_story_5085_50850502_27_dialog_content = "Rasanya masih luar biasa! Andai saja kita bisa menggunakan alkimia untuk memulihkan bagian luarnya...",
  ui_story_5085_50850502_28_dialog_content = "Berbicara tentang itu... apakah alkimia bisa digunakan untuk mengembalikan fragmen relik ini ke bentuk aslinya?",
  ui_story_5085_50850502_29_dialog_content = "Ah, itu adalah potongan-potongan yang kita kumpulkan sebelumnya.",
  ui_story_5085_50850502_30_dialog_content = "Aku mengambil beberapa sendiri, tapi aku tidak yakin jika Ryza bisa menggunakannya atau tidak.",
  ui_story_5085_50850502_31_dialog_content = "Kalian semua adalah pembantu yang luar biasa! Terima kasih telah menjaga mata untuk bahan baru untuk alkimia saya!",
  ui_story_5085_50850502_32_dialog_content = "Kita tidak akan tahu kecuali kita mencoba, bukan? Saya akan lihat apa yang bisa saya buat dari potongan-potongan ini malam ini!",
  ui_story_5085_50850502_33_dialog_content = "Sejak bertemu Ryza, rasanya seolah-olah akhirnya saya memiliki kompetisi serius dalam hal mengais barang!",
  ui_story_5085_50850502_34_dialog_content = "Hahaha, ini mungkin saja bisa memberi kita lebih banyak informasi tentang reruntuhan tersebut.",
  ui_story_5085_50850502_35_dialog_content = "Aku tidak bisa merasakan apa-apa dari potongan-potongan individu ini.",
  ui_story_5085_50850502_36_dialog_content = "Tapi setelah mereka dipulihkan... Mungkin ini akan menjadi kisah yang berbeda sama sekali!",
  ui_story_5085_50850502_37_dialog_content = "Aku akan membereskan atelier agar setiap orang bisa beristirahat dengan baik malam ini.",
  ui_story_5085_50850601_1_dialog_content = "<color=#e8d9bb>Mengomel—Mengomel—</color>",
  ui_story_5085_50850601_2_dialog_content = "... Hah?! Oh... Kurasa mereka juga memiliki burung laut nokturnal di dunia ini...",
  ui_story_5085_50850601_3_dialog_content = "Tidak apa-apa, mereka seharusnya tidak membangunkan siapa pun.",
  ui_story_5085_50850601_4_dialog_content = "Semua orang kelelahan setelah hari ini... Mereka semua sudah tidur pulas.",
  ui_story_5085_50850601_5_dialog_content = "Apakah kamu masih mengawasi kuali, Ryza?",
  ui_story_5085_50850601_6_dialog_content = "Benar! Saya harus terus mengawasi isi untuk memastikan tidak ada yang salah.",
  ui_story_5085_50850601_7_dialog_content = "Hmm, tidak buruk sama sekali... Sedikit lebih lama dan fragmen-fragmen itu seharusnya kembali ke bentuk aslinya!",
  ui_story_5085_50850601_8_dialog_content = "Terdengar seperti kamu bukan orang asing yang mengaduk kuali sepanjang malam. Menjadi seorang alkemis pasti sangat berat...",
  ui_story_5085_50850601_9_dialog_content = "Alchemy adalah seni menciptakan sesuatu dari tidak ada. Sepanjang zaman, para alkemis telah bereksperimen dengan berbagai ide dan metode untuk memberi kita pengetahuan yang kita miliki hari ini.",
  ui_story_5085_50850601_10_dialog_content = "Ahhh, tapi aku masih tidak bisa berhenti khawatir. Apa yang akan kita lakukan jika sesuatu memang salah...?",
  ui_story_5085_50850601_11_dialog_content = "Haha, maka aku akan menemanimu sampai selesai. Aku yakin semuanya akan baik-baik saja!",
  ui_story_5085_50850601_12_dialog_content = "Sebenarnya, saat aku menggunakan kekuatanku untuk merasakan panci ini... Aku mendengar suara yang aneh.",
  ui_story_5085_50850601_13_dialog_content = "Ini menyuruhku untuk kembali.",
  ui_story_5085_50850601_14_dialog_content = "Eh?!",
  ui_story_5085_50850601_15_dialog_content = "Begitukah? Apakah kamu pikir itu panci yang berbicara padamu?",
  ui_story_5085_50850601_16_dialog_content = "Mungkin. Kekuatan psikis saya memberitahu saya bahwa suara ini entah bagaimana terhubung dengan reruntuhan.",
  ui_story_5085_50850601_17_dialog_content = "Terasa seperti roh kuno... Dan itu mencoba berkomunikasi denganku dengan berbicara seolah-olah itu mengenalku.",
  ui_story_5085_50850601_18_dialog_content = "Aku tidak yakin apakah harus mengikuti petunjuk ini atau tidak. Aku bahkan tidak tahu harus mulai dari mana...",
  ui_story_5085_50850601_19_dialog_content = "Saya punya pertanyaan!",
  ui_story_5085_50850601_20_dialog_content = "Ini tentang kekuatanmu. Jika kamu tidak bisa merasakan Eclipsite di sekitar, berarti kita tidak akan bertemu dengan mereka, 'kan?",
  ui_story_5085_50850601_21_dialog_content = "Ya, biasanya memang begitu...",
  ui_story_5085_50850601_22_dialog_content = "Aku mengerti. Kekuatan yang menarik... Hah!",
  ui_story_5085_50850601_23_dialog_content = "<color=#e8d9bb>Krek!</color>",
  ui_story_5085_50850601_24_dialog_content = "A-Apa itu tentang...?!",
  ui_story_5085_50850601_25_dialog_content = "Jangan khawatir, itu hanya bug. Sepertinya ada beberapa hal yang bahkan kekuatanmu tidak bisa mendeteksi, ya?",
  ui_story_5085_50850601_26_dialog_content = "Sepertinya nyamuk, tapi lihat lebih dekat! Matanya benar-benar merah, dan dia menghilang segera setelah saya membunuhnya... Ada kemungkinan besar itu adalah jenis nyamuk Eclipsite.",
  ui_story_5085_50850601_27_dialog_content = "Dan kau bahkan tidak menyadarinya! Apakah ini berarti pulau ini memiliki sifat unik lainnya?",
  ui_story_5085_50850601_28_dialog_content = "Kelihatannya memang begitu...",
  ui_story_5085_50850601_29_dialog_content = "Pulau ini memang penuh dengan misteri.",
  ui_story_5085_50850601_30_dialog_content = "Saya setuju, dan sesuatu memberitahu saya bahwa pulau dan reruntuhan ini juga ingin kita mengungkap rahasia mereka.",
  ui_story_5085_50850601_32_dialog_content = "Lucu, kamu sedang menceritakan ceritamu sebelum burung itu mengganggu...",
  ui_story_5085_50850601_33_dialog_content = "Tapi sekarang, kau mendengarkan aku bicara tentang kekhawatiranku...",
  ui_story_5085_50850601_35_dialog_content = "Jika kita pernah menemukan waktu, aku masih ingin mendengar lebih banyak tentang petualanganmu!",
  ui_story_5085_50850601_37_dialog_content = "Sepertinya kamu benar-benar menyukai petualangan, Ryza.",
  ui_story_5085_50850601_38_dialog_content = "Tapi saya benar-benar bisa mengerti, karena saya juga begitu!",
  ui_story_5085_50850601_39_dialog_content = "Apakah itu melihat hal-hal baru yang aneh atau berpergian dengan teman-teman saya... Saya selalu menghargai setiap momen dari setiap petualangan!",
  ui_story_5085_50850601_40_dialog_content = "<color=#e8d9bb>Antara dua jiwa yang sejenis, kuali alkimia tampaknya beresonansi dengan semangat petualangan mereka dan membuat suara yang menjanjikan.</color>",
  ui_story_5085_50850601_41_dialog_content = "Kita berhasil!",
  ui_story_5085_50850601_42_dialog_content = "Fragmen telah dipulihkan ke bentuk aslinya... Tunggu, sekarang ada tiga! Ada ide apa ini?",
  ui_story_5085_50850601_43_dialog_content = "Itu…",
  ui_story_5085_50850601_44_dialog_content = "... Beberapa jenis <color=#FFB400>lambang</color>?",
  ui_story_5085_50850601_45_dialog_content = "Itu benar, dan ada tiga jenis berbeda dari mereka! Mereka semua sangat cantik!",
  ui_story_5085_50850601_46_dialog_content = "Lihat ini! Sepertinya ada sesuatu yang terukir di atasnya... Sebuah perisai, mungkin? Aku bertanya-tanya apa artinya?",
  ui_story_5085_50850601_47_dialog_content = "Biar kucoba merasakannya.",
  ui_story_5085_50850601_48_option_content = "Force Boost",
  ui_story_5085_50850601_49_dialog_content = "Pangeranku, waktu kita tidak banyak lagi. Kita harus membuat keputusan sebelum terlambat.",
  ui_story_5085_50850601_50_dialog_content = "Relik kuno yang telah kamu perkenalkan kepada kami bekerja cukup baik, tetapi kami belum menguasai kontrolnya.",
  ui_story_5085_50850601_51_dialog_content = "Barisan Eclipsite bertambah setiap hari, dan kami sangat sedih melihatmu dalam keadaan yang sangat lelah dan cemas...",
  ui_story_5085_50850601_52_dialog_content = "Musisi itu memberi tahu kami bahwa kamu berencana meninggalkan kerajaan dan bepergian ke negeri yang jauh.",
  ui_story_5085_50850601_53_dialog_content = "Tapi apa pun yang terjadi, Yang Mulia... Kami akan selalu menghormati keputusan Anda...",
  ui_story_5085_50850601_54_dialog_content = "Apakah ini kenangan dari knight di emblem itu? Sepertinya dia berbicara tentang reruntuhan pulau... Ini bahkan mungkin bisa memberi tahu kita lebih banyak tentang teleportasi!",
  ui_story_5085_50850601_55_dialog_content = "Tolong, bisakah Anda menunjukkan kepada saya bagaimana menggunakan kekuatan reruntuhan ini?",
  ui_story_5085_50850601_56_dialog_content = "Kembali.",
  ui_story_5085_50850601_57_dialog_content = "... Suara itu lagi! Siapa kamu?! Apakah mungkin kamu itu...",
  ui_story_5085_50850601_58_dialog_content = "Kembali! Kejayaanmu menanti...!",
  ui_story_5085_50850601_59_dialog_content = "<size=50>\"Ketika pangeran pengembara kembali, begitu pula kemuliaan kerajaan kita!\"</size>",
  ui_story_5085_50850601_60_dialog_content = "... Hah?!?",
  ui_story_5085_50850601_61_option_content = "Pikiran... Mulai telepati!",
  ui_story_5085_50850601_62_dialog_content = "Argh…",
  ui_story_5085_50850601_63_dialog_content = ".. PlayerName! Kenapa?!",
  ui_story_5085_50850601_64_dialog_content = "Jangan coba lakukan semuanya sendirian! Kamu masih punya aku, serta teman-teman kita yang lain!",
  ui_story_5085_50850601_65_dialog_content = "... Teman...",
  ui_story_5085_50850601_66_dialog_content = "Ada rumor tentang mechs kuno di reruntuhan. Rasa penasaranku semakin menguasai diri. Aku harus melihatnya sendiri.",
  ui_story_5085_50850601_67_dialog_content = "Atau beberapa mecha kuno legendaris!",
  ui_story_5085_50850601_68_dialog_content = "... Itu Fleur! Ini suara Fleur! Apa yang telah kamu lakukan padanya?!",
  ui_story_5085_50850601_69_dialog_content = "Kembali... Kembali... ke reruntuhan...",
  ui_story_5085_50850601_70_dialog_content = "Tidak, menjauhlah! Reruntuhan ini berbahaya! Kesadaran yang bersemayam di dalamnya telah mengubah ingatanku dan mengambil alih tubuhku!",
  ui_story_5085_50850601_71_dialog_content = "Apa pun yang kamu lakukan... Jangan mendekati reruntuhan itu!!!",
  ui_story_5085_50850601_72_dialog_content = "!!!",
  ui_story_5085_50850601_73_dialog_content = "PlayerName! Sadarkan dirimu!",
  ui_story_5085_50850601_74_dialog_content = "Eclipsite muncul saat kamu menggunakan kekuatanmu! Kita harus bertarung!",
  ui_story_5085_50850602_1_dialog_content = "Hah! Tidak ada jalan keluar!",
  ui_story_5085_50850602_2_dialog_content = "Ryza! Navigator!",
  ui_story_5085_50850602_3_dialog_content = "Kami mendengar gangguan di sini! Apakah salah satu dari kalian terluka?",
  ui_story_5085_50850602_4_dialog_content = "Tidak, kami baik-baik saja...",
  ui_story_5085_50850602_5_dialog_content = "Sebuah suara besar baru saja menggema di seluruh pulau, seolah-olah seluruh pulau mulai bergerak atau semacamnya.",
  ui_story_5085_50850602_6_dialog_content = "Eclipsite tampaknya juga jauh lebih gelisah.",
  ui_story_5085_50850602_7_dialog_content = "Wow, aku bertanya-tanya apakah kita menemukan rahasia lainnya?",
  ui_story_5085_50850602_8_dialog_content = "A-Apa jenis rahasia yang kamu bicarakan?!",
  ui_story_5085_50850602_9_dialog_content = "Ini berkaitan dengan lambang-lambang yang telah kita pulihkan dan kerajaan yang dulu ada di sini... Dan juga apa yang telah pulau ini lakukan kepada kita!",
  ui_story_5085_50850602_10_dialog_content = "<color=#e8d9bb>Di bawah sinar bulan yang suram, sejarah kerajaan kuno perlahan terungkap kepada semua...</color>",
  ui_story_5085_50850602_11_dialog_content = "... Dan kurang lebih itulah yang terjadi. Kita harus menyelamatkan Fleur dan menghilangkan kehadiran jahat yang mengendalikan tubuhnya!",
  ui_story_5085_50850602_12_dialog_content = "Sebuah sihir yang bisa menghapus ingatan teman seseorang... Sungguh hina.",
  ui_story_5085_50850602_13_dialog_content = "Meskipun aku mengingatnya sekarang, aku masih merasa sangat menyesal telah melupakannya...",
  ui_story_5085_50850602_14_dialog_content = "Bagaimana berani reruntuhan busuk itu melemparkan mantra padaku! Catat kata-kataku, aku akan mengubah mereka menjadi tumpukan puing yang lebih besar sebelum kita selesai di sini!",
  ui_story_5085_50850602_15_dialog_content = "Jadi sepertinya... Kekuatan reruntuhan ini lah yang membawa kita ke sini dari dunia kita sendiri...",
  ui_story_5085_50850602_17_dialog_content = "Berdasarkan apa yang Ryza dan Navigator katakan, ketiga emblem ini mungkin menjadi kunci untuk mengalahkan reruntuhan.",
  ui_story_5085_50850602_18_dialog_content = "Tidak peduli apa pun ini mungkin, kita tidak akan mendapatkan apa pun kecuali kita menyelidikinya sendiri!",
  ui_story_5085_50850602_20_dialog_content = "Aku setuju. Entah itu dendam seseorang atau teknologi dari masa lalu, selalu ada solusi. Sekarang mari kita bersiap-siap untuk pergi!",
  ui_story_5085_50850602_21_dialog_content = "Sementara setiap orang sedang membuat persiapan mereka, saya akan merasakan dua lambang lainnya dan melihat apa lagi yang bisa saya temukan.",
  ui_story_5085_50850701_1_dialog_content = "Force Boost",
  ui_story_5085_50850701_2_dialog_content = "Tiga emblem... sesuai dengan tiga teman terdekat pangeran.",
  ui_story_5085_50850701_3_dialog_content = "Seorang ksatria gagah yang memerangi musuh dengan pedangnya...",
  ui_story_5085_50850701_4_dialog_content = "Seorang mage yang mempelajari sejarah kuno dalam pencarian kebijaksanaan misterius...",
  ui_story_5085_50850701_5_dialog_content = "Dan seorang musisi pengadilan, yang melodi-melodinya dapat memberi semangat bahkan pada hati yang paling ragu...",
  ui_story_5085_50850701_6_dialog_content = "Mereka adalah subjek paling setia pangeran, dan mereka berjuang di sisinya dalam suka dan duka.",
  ui_story_5085_50850701_7_dialog_content = "Namun, saat dia pergi, ketiganya tetap tinggal untuk menyambut kepulangannya...",
  ui_story_5085_50850701_8_dialog_content = "\"Ketika pangeran pengembara kembali, begitu pula kemuliaan kerajaan kita!\"",
  ui_story_5085_50850701_9_dialog_content = "Saya mengerti. Jadi itu maksudnya.",
  ui_story_5085_50850701_10_dialog_content = "Tapi kerajaan ini sekarang hanyalah reruntuhan... Dan di atas itu semua, reruntuhan ini telah kehilangan kendali sepenuhnya.",
  ui_story_5085_50850701_11_dialog_content = "Apakah ini berarti bahwa sang pangeran tidak pernah kembali, meskipun kerajaannya diserang oleh Eclipsite?",
  ui_story_5085_50850701_12_dialog_content = "Sementara itu, tiga teman terdekatnya tetap di pulau itu untuk menunggunya...",
  ui_story_5085_50850701_13_dialog_content = "Tapi sekarang, karena tidak ada satupun dari mereka di sini, kesadaran di dalam reruntuhan itu perlahan mulai kehilangan kendali...",
  ui_story_5085_50850701_14_dialog_content = "Memilih secara acak untuk menangkap orang atas nama pangeran?",
  ui_story_5085_50850701_16_dialog_content = "Mengapa dia meninggalkan pulau itu saat dia memiliki perlindungan dari reruntuhan kuno dan teman-teman terdekatnya?",
  ui_story_5085_50850701_18_dialog_content = "Dia mungkin terdengar seperti pengecut... Tapi mungkin dia punya alasan untuk tidak kembali?",
  ui_story_5085_50850701_19_dialog_content = "Yah, kita tidak akan mendekati kebenaran jika kita hanya duduk-duduk dan menebak-nebak seperti ini.",
  ui_story_5085_50850701_20_dialog_content = "Jawaban-jawaban itu kemungkinan besar menunggu kita di akhir petualangan kita.",
  ui_story_5085_50850701_21_dialog_content = "Benar! Misi kita adalah untuk mengungkap rahasia dari reruntuhan itu dan menyelamatkan teman Navigator!",
  ui_story_5085_50850701_22_dialog_content = "Setuju. Jalan di depan tidak akan mudah, tetapi kita tidak bisa menyerah.",
  ui_story_5085_50850702_1_dialog_content = "<color=#e8d9bb>Saat kami menembus hutan, saya tetap waspada untuk tanda-tanda tujuan kami.</color>",
  ui_story_5085_50850702_2_dialog_content = "<color=#e8d9bb>Tapi ketika kita mencapai puncak gunung, reruntuhan akhirnya mulai terlihat.</color>",
  ui_story_5085_50850702_3_dialog_content = "Kita... Akhirnya... berhasil sampai di titik ini!",
  ui_story_5085_50850702_4_dialog_content = "Apakah gerbang batu kuno ini adalah pintu masuk ke reruntuhan? Jika iya... Bagaimana kita bisa masuk...?",
  ui_story_5085_50850702_5_dialog_content = "Hei! Lihatlah lubang-lubang ini di gerbang, teman-teman!",
  ui_story_5085_50850702_6_dialog_content = "Mereka tampaknya cocok dengan bentuk dari tiga lambang itu dengan sempurna! Mungkin mereka benar-benar adalah kuncinya!",
  ui_story_5085_50850702_7_dialog_content = "PlayerName, dapatkah Anda merasakan jika ada Eclipsite di sekitar?",
  ui_story_5085_50850702_8_option_content = "Mindlink!",
  ui_story_5085_50850702_9_dialog_content = "Tidak ada Eclipsite di sisi lain gerbang, tapi...",
  ui_story_5085_50850702_10_dialog_content = "Pasti ada sesuatu di sana...",
  ui_story_5085_50850702_11_dialog_content = "Kamu bisa merasakannya juga, Ryza?",
  ui_story_5085_50850702_12_dialog_content = "Mungkin karena aku memegang emblem ini, tapi aku merasakan rasa rindu yang kuat datang dari sisi lain. Sangat sedih... Dan anehnya memberi kenyamanan.",
  ui_story_5085_50850702_13_dialog_content = "Ayo kita taruh dulu emblem-emblemnya di tempatnya.",
  ui_story_5085_50850702_14_dialog_content = "<color=#e8d9bb>Klik, klik, klik—</color>",
  ui_story_5085_50850702_15_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_5085_50850702_16_dialog_content = "A-Apa yang terjadi?!",
  ui_story_5085_50850702_17_dialog_content = "Tunggu... Seseorang datang!",
  ui_story_5085_50850702_18_dialog_content = "Di atas sana!!",
  ui_story_5085_50850702_19_dialog_content = "Kamu benar... Tapi kapan mereka muncul?!",
  ui_story_5085_50850702_20_dialog_content = "Selamat datang di kerajaan saya—",
  ui_story_5085_50850702_21_dialog_content = "F-Fleur?!",
  ui_story_5085_50850702_22_dialog_content = "Tidak, itu adalah kesadaran di dalam reruntuhan! Itu mengendalikan tubuh Fleur...",
  ui_story_5085_50850702_23_dialog_content = "Dan memaksanya untuk berperan sebagai \"pangeran pengembara\"!",
  ui_story_5085_50850702_24_dialog_content = "Saya ucapkan selamat pagi, teman Caelestite yang berkelana.",
  ui_story_5085_50850702_25_dialog_content = "Para aktor dalam drama ini tidak begitu penting. Dalam pencariannya untukmu, dia tersandung pada tempat ini...",
  ui_story_5085_50850702_26_dialog_content = "Dan begitu reruntuhan itu menjadikannya sebagai pangeran.",
  ui_story_5085_50850702_27_dialog_content = "Ah—Betapa aku telah meratapi kehilangan kerajaanku, dan betapa tak seorang pun yang datang membela! Tapi sekarang, saatnya telah tiba untuk memanggil subjek-subjek setiaku.",
  ui_story_5085_50850702_28_option_content = "Force Boost!",
  ui_story_5085_50850702_29_dialog_content = "Fleur! Keluar darinya!",
  ui_story_5085_50850702_30_dialog_content = "Wah—",
  ui_story_5085_50850702_31_dialog_content = "Kepalaku... Tiba-tiba berdenyut-denyut...",
  ui_story_5085_50850702_32_dialog_content = "K-Kekuatanmu tidak berfungsi, ! Menggunakannya hanya akan membuat \"pangeran\" memberikan tekanan psikis pada kita semua...",
  ui_story_5085_50850702_33_dialog_content = "Jeritan putus asa Anda adalah musik bagi telinga saya. Melalui tindakan sembrono Anda sendiri, Anda telah membawa rasa sakit dan penderitaan kepada rakyat Anda—",
  ui_story_5085_50850702_34_dialog_content = "Mereka bukan bawahan saya! Mereka adalah teman-teman saya! Dan—",
  ui_story_5085_50850702_35_dialog_content = "Kamu juga salah satu dari kami!!!",
  ui_story_5085_50850702_36_dialog_content = "...",
  ui_story_5085_50850702_37_dialog_content = "Saya... adalah seorang aktor... Diberkati dengan kenangan sang pangeran...",
  ui_story_5085_50850702_38_dialog_content = "Ehem... Sekarang, mari kita lanjutkan pertunjukan kita yang gemilang...",
  ui_story_5085_50850702_39_dialog_content = "Para pelancong dari jauh! Bukti apa yang kalian miliki untuk mengidentifikasi diri kalian sebagai subjek paling setia saya?",
  ui_story_5085_50850702_40_dialog_content = "Hanya ada satu jalan ke depan: selesaikan quest-questku, dan bangkitkan kenangan di dalam emblem ini!",
  ui_story_5085_50850702_41_dialog_content = "Hanya dengan begitu aku akan memberimu izin lewat.",
  ui_story_5085_50850702_42_dialog_content = "Hah?? Apakah itu berarti kamu akan membiarkan kami masuk ke reruntuhan?",
  ui_story_5085_50850702_43_dialog_content = "Kita hanya perlu menyelesaikan \"quest\" ini, benar?",
  ui_story_5085_50850702_44_dialog_content = "Maka masih ada harapan! Selama kita berhasil masuk ke reruntuhan, kita memiliki kesempatan untuk menyelamatkan Fleur!",
  ui_story_5085_50850702_45_dialog_content = "Dengarkan kata-kataku, para pelancong! Quest dari Emblem's Knight—",
  ui_story_5085_50850702_46_dialog_content = "\"Bunuh seratus monster penghisap darah, agar kerajaan kita akhirnya dapat tidur dalam damai dan kenyamanan.\"",
  ui_story_5085_50850702_47_dialog_content = "\"Monster penghisap darah\"...? A-Apakah benar ada makhluk menakutkan seperti itu di pulau ini?",
  ui_story_5085_50850702_48_dialog_content = "Monster penghisap darah... Mungkinkah itu yang pernah saya lihat dengan PlayerName sebelumnya?",
  ui_story_5085_50850702_49_dialog_content = "Berikutnya adalah quest dari Emblem Musisi—",
  ui_story_5085_50850702_50_dialog_content = "\"Tawarkan kepada prajurit kerajaan kita malam tidur yang tenang dengan lagu pengantar tidur yang paling menenangkan di dunia.\"",
  ui_story_5085_50850702_51_dialog_content = "... Lagu pengantar tidur?!",
  ui_story_5085_50850702_52_dialog_content = "Itu adalah skenario terburuk untuk idola yang suka rock keras seperti saya!!",
  ui_story_5085_50850702_53_dialog_content = "Dan akhirnya, quest dari Emblem Mage—",
  ui_story_5085_50850702_54_dialog_content = "\"Panggil angin ajaib untuk mengayun istana dalam hembusan angin lembut dan menyenangkan selamanya.\"",
  ui_story_5085_50850702_55_dialog_content = "...",
  ui_story_5085_50850702_56_dialog_content = "...",
  ui_story_5085_50850702_57_dialog_content = "Mengapa semua quest ini ada hubungannya dengan tidur?!?",
  ui_story_5085_50850702_58_dialog_content = "Heheheh... Sepertinya pangeran mengalami insomnia yang cukup serius...",
  ui_story_5085_50850702_59_dialog_content = "Apakah ini sebabnya pangeran meninggalkan kerajaannya pada awalnya? Ridikulus—",
  ui_story_5085_50850702_60_dialog_content = "Saya bertanya-tanya... Bagaimana kita seharusnya menciptakan angin sepoi-sepoi yang abadi untuk \"mengayun istana\"?",
  ui_story_5085_50850702_62_dialog_content = "Ketika tiga emblem terbangun, kerajaan kita akan lahir kembali.",
  ui_story_5085_50850702_63_dialog_content = "Aku yakin bahwa... Kamu akan menemukan jawabannya.",
  ui_story_5085_50850702_64_dialog_content = "Sungguh serangkaian quest yang merepotkan.",
  ui_story_5085_50850702_65_dialog_content = "Saya hanya bersyukur kita telah diberi jalan ke depan. Setidaknya kita tahu apa yang harus kita lakukan sekarang.",
  ui_story_5085_50850702_66_dialog_content = "Bagaimana menurutmu, Ryza?",
  ui_story_5085_50850702_67_dialog_content = "Mari terus bergerak. Saya yakin jawabannya akan segera terungkap.",
  ui_story_5085_50850702_68_dialog_content = "Sebenarnya... Aku sudah memiliki beberapa ide untuk menyelesaikan quest-quest ini!",
  ui_story_5085_50850800_1_dialog_content = "Uh-oh, kami punya lebih banyak Eclipsite!",
  ui_story_5085_50850800_2_dialog_content = "Di mana kita seharusnya menemukan \"monster penghisap darah\" ini untuk pencarian Knight?",
  ui_story_5085_50850800_3_dialog_content = "Sebenarnya, Navigator dan saya sudah memiliki rencana untuk itu!",
  ui_story_5085_50850800_4_dialog_content = "Itulah mengapa saya pikir pencarian Emblem Knight tidak akan menjadi masalah bagi kita!",
  ui_story_5085_50850800_5_dialog_content = "Misi Mage mungkin akan menjadi yang paling merepotkan... Bagaimana kita seharusnya menciptakan sesuatu yang bisa memanggil angin sejuk yang tak pernah berhenti?",
  ui_story_5085_50850800_6_dialog_content = "Sebenarnya, saya punya beberapa ide yang mungkin berguna untuk kamu, Ryza!",
  ui_story_5085_50850900_1_dialog_content = "Luar biasa... Berkat bantuan Miss Vice, sepertinya Ryza telah menemukan arah baru untuk dieksplorasi dengan alkimianya.",
  ui_story_5085_50850900_2_dialog_content = "Benarkah? Itu bagus! Saya juga telah membuat kemajuan di sisi saya.",
  ui_story_5085_50850900_3_dialog_content = "Segera, kita akan memiliki dua emblem terbangun di tangan kita!",
  ui_story_5085_50850900_4_dialog_content = "Bagaimana dengan kamu, Klaudia? Kamu dan Barbara sepertinya bisa bekerja sama dengan baik.",
  ui_story_5085_50850900_5_dialog_content = "Kami juga telah membuat banyak kemajuan, tapi aku masih sedikit gugup...",
  ui_story_5085_50850902_1_dialog_content = "Maaf untuk menunggu—",
  ui_story_5085_50850902_2_dialog_content = "Saya pikir... Saya pikir kita telah melakukannya!",
  ui_story_5085_50850902_3_dialog_content = "Aku yakin pangeran pasti tak menyangka kita akan menyelesaikan misinya dengan begitu cepat!",
  ui_story_5085_50850902_4_dialog_content = "Hei—kesadaran dari reruntuhan, atau siapapun kamu—",
  ui_story_5085_50850902_5_dialog_content = "Kami sudah menyelesaikan ketiga quest Anda!",
  ui_story_5085_50850902_6_dialog_content = "... Kamu harus memberitahuku terlebih dahulu bagaimana kamu mencapai targetmu.",
  ui_story_5085_50850902_7_dialog_content = "Ayo kita mulai.",
  ui_story_5085_50850902_8_dialog_content = "Ya!",
  ui_story_5085_50850902_9_dialog_content = "Pertama, Emblem Knight!",
  ui_story_5085_50850902_10_dialog_content = "... Zarya dan aku menyelesaikan itu bersama-sama!",
  ui_story_5085_50850902_11_dialog_content = "S-Sebagai penjaga kerajaan Queen Bethlehem... Aku lebih dari bersedia untuk menjalankan misi seorang knight!",
  ui_story_5085_50850902_12_dialog_content = "Dengan kekuatan kita yang bersatu, kita berhasil membasmi seratus nyamuk Eclipsite dari pulau itu!",
  ui_story_5085_50850902_13_dialog_content = "Itu harus memenuhi persyaratan quest untuk membunuh \"seratus monster penghisap darah,\" bukan?",
  ui_story_5085_50850902_14_dialog_content = "Saya hanya berharap kita bisa memasukkan yang Ryza dan saya pukul malam sebelumnya...",
  ui_story_5085_50850902_15_dialog_content = "Selanjutnya, Emblem Musisi!",
  ui_story_5085_50850902_16_dialog_content = "Yeah, yeah, yeah! Dalam hal musik, tidak ada tantangan yang terlalu besar untuk idola nomor satu, Barbara!",
  ui_story_5085_50850902_17_dialog_content = "Dan dengan dukungan luar biasa dari Nona Klaudia...",
  ui_story_5085_50850902_18_dialog_content = "Musik kami yang sudah luar biasa menjadi kekuatan suara yang tak terhentikan!",
  ui_story_5085_50850902_19_dialog_content = "Heheh, saya hanya menyediakan pengiring instrumen untuk suara indah Miss Barbara.",
  ui_story_5085_50850902_20_dialog_content = "Nyanyiannya benar-benar spektakuler!",
  ui_story_5085_50850902_21_dialog_content = "Yang kita lakukan hanyalah mengubah mode ekspresi; cinta di hatiku masih terbakar sehangat biasanya!",
  ui_story_5085_50850902_22_dialog_content = "Dan dengan itu, kami memberikan lagu pengantar tidur termanis yang pernah didengar oleh prajurit kerajaan!",
  ui_story_5085_50850902_23_dialog_content = "Dan akhirnya, Emblem Mage!",
  ui_story_5085_50850902_24_dialog_content = "Lihatlah! Inilah kekuatan—",
  ui_story_5085_50850902_25_dialog_content = "Dengan alkimiku! Dengan bantuan semua orang, kita telah menciptakan generator angin terbaik!",
  ui_story_5085_50850902_26_dialog_content = "Saya menyediakan desain, Zarya menyediakan es batu, dan Ryza menyediakan bagian-bagiannya. Setelah itu, kita semua bekerja sama untuk merakitnya.",
  ui_story_5085_50850902_27_dialog_content = "Meski di Illumina, kami biasanya menyebutnya sebagai \"AC\" atau sesuatu sejenis itu...",
  ui_story_5085_50850902_28_dialog_content = "Tapi namanya tidak penting!",
  ui_story_5085_50850902_29_dialog_content = "Dengan mesin ini, kami bisa memanggil angin ajaib untuk \"membuai istana dalam angin sepoi-sepoi yang lembut dan menyenangkan\"!",
  ui_story_5085_50850902_30_dialog_content = "Untuk Aurorian kuno yang pernah tinggal di sini, perangkat canggih dan nyaman seperti ini pasti lebih mengesankan daripada sihir!",
  ui_story_5085_50850902_31_dialog_content = "Begitu... Jadi ini jawaban-jawaban yang kamu bawa untukku.",
  ui_story_5085_50850902_32_dialog_content = "Meski begitu...",
  ui_story_5085_50850902_33_dialog_content = "Sebelum memberikanmu izin masuk, aku harus yakin akan kesetiaanmu.",
  ui_story_5085_50850902_34_dialog_content = "Sekarang kamu harus membuktikan kepada saya bahwa persahabatan lebih berharga daripada emas!",
  ui_story_5085_50850902_35_dialog_content = "Setelah semua lari-larian itu, sekarang kamu ingin kami membuktikan persahabatan kami?!",
  ui_story_5085_50850902_36_dialog_content = "Mungkin dia hanya ingin kita membuktikan persahabatan antara pangeran dan pemilik lambang-lambang ini?",
  ui_story_5085_50850902_37_dialog_content = "Tapi itu sama sekali berlebihan!",
  ui_story_5085_50850902_38_dialog_content = "Itu baik, saya dengan senang hati akan membuktikannya kepada Anda!",
  ui_story_5085_50850902_39_dialog_content = "Hah?",
  ui_story_5085_50850902_40_dialog_content = "Dan itu karena—Kita adalah teman terdekat sang pangeran!",
  ui_story_5085_50850902_41_dialog_content = "Semua yang telah kita lakukan sejauh ini adalah untuk melayani \"pangeran\" saat ini. Itu sepenuhnya benar.",
  ui_story_5085_50850902_42_dialog_content = "Dan jika kamu tidak percaya padaku, aku akan menggunakan kehangatan di tangan ini untuk membuktikannya kepadamu!",
  ui_story_5085_50850902_43_dialog_content = "...",
  ui_story_5085_50850902_44_dialog_content = "Ayolah, setiap orang! Bantu Navigator mendorong membuka gerbang!",
  ui_story_5085_50850902_45_dialog_content = "Ryza... PlayerName...",
  ui_story_5085_50850902_46_dialog_content = "Kita tidak bisa terhenti di tempat seperti ini! Ayo pergi!",
  ui_story_5085_50850902_47_dialog_content = "Aku akan membantu PlayerName juga!",
  ui_story_5085_50850902_48_dialog_content = "Salah satu anggota Rediesel Wrench ada di sana! Saya memiliki kewajiban untuk membawanya pulang!",
  ui_story_5085_50850902_49_dialog_content = "A-Aku berjanji pada diri sendiri... Bahwa aku tidak akan pernah kalah lagi pada siapa pun!",
  ui_story_5085_50850902_50_dialog_content = "\"Letakkan tanganmu di gerbang dan bukalah dengan hatimu.\"",
  ui_story_5085_50850902_51_dialog_content = "Kehangatan ini... Gairah ini...",
  ui_story_5085_50850902_52_dialog_content = "Kemuliaan masa lalu kita akhirnya muncul kembali.",
  ui_story_5085_50850902_53_dialog_content = "Pintu ke kerajaanku selalu terbuka untukmu!",
  ui_story_5085_50850902_54_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5085_50850902_55_dialog_content = "Kita berhasil!",
  ui_story_5085_50851001_1_dialog_content = "Akhirnya kita berhasil masuk ke reruntuhan!",
  ui_story_5085_50851001_2_dialog_content = "Wow, sama menakjubkannya dari dalam! Saya yakin tempat ini terlihat sangat mengesankan di masa lalu!",
  ui_story_5085_50851001_3_dialog_content = "Kita harus tetap berhati-hati. Waktu telah menggerogoti sebagian besar bagian dalam...",
  ui_story_5085_50851001_4_dialog_content = "Kita tidak bisa melupakan tentang kesadaran juga. Tidak ada yang tahu apa yang sedang dia rencanakan sekarang.",
  ui_story_5085_50851001_5_dialog_content = "Ugh! Kami akhirnya berhasil membuka gerbangnya, tetapi Fleur tidak ditemukan lagi!",
  ui_story_5085_50851001_6_dialog_content = "Lihat ke sana—Apakah itu takhta?",
  ui_story_5085_50851001_7_dialog_content = "Ada seseorang yang sedang duduk di atasnya! Mungkin itu Fleur...",
  ui_story_5085_50851001_8_dialog_content = "Hei, ini benar-benar dia!",
  ui_story_5085_50851001_9_dialog_content = "Fleur—!",
  ui_story_5085_50851001_10_dialog_content = "...",
  ui_story_5085_50851001_11_option_content = "Telepati—",
  ui_story_5085_50851001_12_dialog_content = "<color=#e8d9bb>Meretih-</color>",
  ui_story_5085_50851001_13_dialog_content = "Aku tidak ingat kapan ini dimulai, tapi Eclipsites mulai menyerang kami setiap malam.",
  ui_story_5085_50851001_14_dialog_content = "Hingga hari ini, saya masih tidak tahu kapan atau mengapa mereka muncul, tetapi mereka telah membawa penderitaan dan kesakitan yang tak terhitung bagi kaum saya.",
  ui_story_5085_50851001_15_dialog_content = "Malam demi malam tanpa tidur, saya menyaksikan teman dan orang-orang yang saya cintai diambil dari saya satu per satu.",
  ui_story_5085_50851001_16_dialog_content = "Dan jadi, aku memutuskan untuk meninggalkan kerajaan dan mencari bantuan dari daratan utama. Raja seharusnya tidak dipaksa untuk menghadapi krisis ini sendirian.",
  ui_story_5085_50851001_17_dialog_content = "O roh bijaksana dan kuno dari reruntuhan... Tolong ingat niatku.",
  ui_story_5085_50851001_18_dialog_content = "Jika aku kembali dengan kemenangan, janjilah bahwa kamu akan menyanjungku. Tetapi jika aku tidak pernah kembali, tolong jangan berkabung untukku...",
  ui_story_5085_50851001_19_dialog_content = "Ketiga <color=#FFB400>emblem ini</color> melambangkan tiga orang dengan karakter moral tertinggi.",
  ui_story_5085_50851001_20_dialog_content = "Di tangan yang layak, lambang-lambang ini suatu hari nanti akan membawa kehidupan baru bagi kerajaan kita...",
  ui_story_5085_50851001_21_dialog_content = "Pangeran...",
  ui_story_5085_50851001_22_dialog_content = "Sehat?",
  ui_story_5085_50851001_23_dialog_content = "... Fleur masih belum sadar, tapi saya pikir saya tahu mengapa kamu dan teman-temanmu dipanggil ke dunia ini, Ryza...",
  ui_story_5085_50851001_24_dialog_content = "Hah?!",
  ui_story_5085_50851001_25_dialog_content = "Pangeran meninggalkan pulau untuk meminta bantuan dari daratan utama, dan dia mempercayakan reruntuhan dengan pesan terakhirnya.",
  ui_story_5085_50851001_26_dialog_content = "Jika dia gagal kembali, kerajaan akan ditinggalkan di tangan tiga orang yang membawa lambang-lambang ini...",
  ui_story_5085_50851001_27_dialog_content = "Ksatria, Penyihir, dan Musisi...?",
  ui_story_5085_50851001_28_dialog_content = "Maka itu berarti... Pangeran itu tidak pernah kembali...",
  ui_story_5085_50851001_29_dialog_content = "Benar, dan dalam hitungan tahun tak terhingga setelah keruntuhan kerajaannya...",
  ui_story_5085_50851001_30_dialog_content = "Reruntuhan itu telah menunggu kembalinya pangeran, dan mencari tanpa henti tiga orang yang layak untuk mengambil lambang-lambang ini dan memulihkan kerajaan.",
  ui_story_5085_50851001_31_dialog_content = "Dan karena kalian semua layak mendapatkan lambang, puing-puing memanggilmu ke sini dari dunia lain karena kesalahan. Jika saya harus menebak, itu mungkin sekitar waktu Fleur salah dikenali sebagai pangeran dan terjebak di sini.",
  ui_story_5085_50851001_32_dialog_content = "Jadi begitulah kejadiannya! Lalu sang pangeran sejati...",
  ui_story_5085_50851001_33_dialog_content = "Apakah dia berhasil kembali dengan selamat atau tidak, dia sekarang tidak lebih dari mimpi yang tak terjangkau.",
  ui_story_5085_50851001_34_dialog_content = "Sungguh cara yang mengerikan untuk segalanya berakhir...",
  ui_story_5085_50851001_35_dialog_content = "Awas! Di atas kita!!",
  ui_story_5085_50851001_36_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5085_50851001_37_dialog_content = "Reruntuhan mulai bergetar!",
  ui_story_5085_50851001_38_dialog_content = "Ah... Ahhhhhhh—",
  ui_story_5085_50851001_39_dialog_content = "Fleur?! Ap-Ap-Apa yang salah denganmu?!",
  ui_story_5085_50851001_40_dialog_content = "Ah!",
  ui_story_5085_50851001_41_dialog_content = "Kita harus keluar dari sini! Jika reruntuhan ini mulai kehilangan kendali, maka Fleur adalah—",
  ui_story_5085_50851001_42_dialog_content = "Fleur... Dia menjadi satu dengan batu dan mesin dari reruntuhan!",
  ui_story_5085_50851001_43_dialog_content = "Apakah dia menjadikan dirinya sendiri sebagai mecha?!",
  ui_story_5085_50851001_44_dialog_content = "Hah?",
  ui_story_5085_50851001_45_dialog_content = "Jadi, apakah reruntuhan ini yang melakukannya? Atau bisa jadi Fleur akhirnya melawan kendali mereka?",
  ui_story_5085_50851001_46_dialog_content = "Saya tidak berpikir itu adalah kekhawatiran terbesar kita saat ini!",
  ui_story_5085_50851001_47_dialog_content = "Dia akan meratakan tempat ini jika kita tidak segera menghentikannya!!!",
  ui_story_5085_50851001_48_dialog_content = "Kerajaan harus terlahir kembali... Saya harus mewujudkan mimpi kita!",
  ui_story_5085_50851001_49_dialog_content = "Hraaaaaah—!",
  ui_story_5085_50851002_1_dialog_content = "Dia mulai hancur! Sekarang, Navigator!",
  ui_story_5085_50851002_2_dialog_content = "Siap!",
  ui_story_5085_50851002_3_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5085_50851002_4_dialog_content = "Fleur! Apa kamu baik-baik saja?!",
  ui_story_5085_50851002_5_dialog_content = "Mechaku... Kerajaanku...",
  ui_story_5085_50851002_6_dialog_content = "Dia masih belum sadar... Aku akan membawanya keluar dari sini... Hmm?",
  ui_story_5085_50851002_7_dialog_content = "?!?",
  ui_story_5085_50851002_8_dialog_content = "Kalian bertiga tiba-tiba bersinar...",
  ui_story_5085_50851002_9_dialog_content = "... Seperti tiga emblem!",
  ui_story_5085_50851002_10_dialog_content = "Aku mengerti... Pangeran sejak awal ingin kita berkumpul di sini.",
  ui_story_5085_50851002_11_dialog_content = "Dan sekarang ketika kesadarannya telah hilang... Saatnya juga bagi penyelamat pilihan kerajaannya untuk kembali.",
  ui_story_5085_50851002_12_dialog_content = "Namun…",
  ui_story_5085_50851002_13_dialog_content = "Reruntuhan... Dan gunung ini seluruhnya! Semuanya hampir runtuh!",
  ui_story_5085_50851002_14_dialog_content = "Bukan hanya gunung... Seluruh pulau bergetar! Apa yang harus kita lakukan...?",
  ui_story_5085_50851002_15_dialog_content = "Menuju pantai. Temanmu sedang menunggu di sana.",
  ui_story_5085_50851002_16_dialog_content = "Fleur? Tidak, tunggu... Kamu adalah pangeran, bukan? Apa yang kamu maksud dengan \"teman kami\"?",
  ui_story_5085_50851002_17_dialog_content = "Dia benar, kamu tahu! Setidaknya kita akan aman dari puing yang jatuh di pantai, jadi ayo bergegas!",
  ui_story_5085_50851002_18_dialog_content = "Maka tampaknya ini adalah quest terakhir kita...",
  ui_story_5085_50851002_19_dialog_content = "Adalah untuk mengawal semua orang dengan aman ke pantai sebelum kita kembali ke dunia kita sendiri! Masih ada waktu!",
  ui_story_5085_50851002_20_dialog_content = "Benar! Ayo bergegas!",
  ui_story_5085_50851002_21_dialog_content = "Kalian...",
  ui_story_5085_50851002_22_dialog_content = "Saya hanya berharap kami akan memiliki kesempatan untuk mengucapkan selamat tinggal begitu kami sampai di sana!",
  ui_story_5085_50851100_1_dialog_content = "Hei—di sini—",
  ui_story_5085_50851100_2_dialog_content = "Tuan Corax—!",
  ui_story_5085_50851100_3_dialog_content = "(Jadi teman yang dia sebutkan adalah Corax, huh.)",
  ui_story_5085_50851100_4_dialog_content = "Apakah semua orang aman? Kapal penyelamat akan segera mendarat, jadi tolong tahan sedikit lebih luka.",
  ui_story_5085_50851100_5_dialog_content = "Fyuh... Akhirnya kita sampai juga ke perahu. Kita tidak lupa siapa pun kali ini, bukan?",
  ui_story_5085_50851100_6_dialog_content = "Aku tidak melihat Ryza dimanapun... Ryza! Kamu ada di mana?!",
  ui_story_5085_50851100_7_dialog_content = "Aku... Aku di sini!",
  ui_story_5085_50851100_8_dialog_content = "Maaf jika saya membuat siapa saja khawatir.",
  ui_story_5085_50851100_9_dialog_content = "Jika semua orang ada di sini sekarang, saya akan memberi tahu Tuan Corax bahwa kita siap untuk berlayar.",
  ui_story_5085_50851100_10_dialog_content = "Pulau itu... Pada akhirnya, tenggelam ke laut...",
  ui_story_5085_50851100_11_dialog_content = "Ya, dan tanpa jejak keberadaannya yang tertinggal.",
  ui_story_5085_50851100_12_dialog_content = "Ada pergi uangku untuk merawat Colossus...",
  ui_story_5085_50851100_13_dialog_content = "Heheh, aku tidak akan begitu yakin! Lihat ini, semuanya—",
  ui_story_5085_50851100_14_dialog_content = "Apakah ini... Serpihan-serpihan dari takhta raja? Apakah ini alasanmu lama kembali, Ryza?!",
  ui_story_5085_50851100_15_dialog_content = "Yep! Meskipun itu berbahaya, kamu terus menggunakan kekuatanmu untuk mencari kebenaran... Jadi, tentu saja saya harus membantu dengan cara saya sendiri juga!",
  ui_story_5085_50851100_17_dialog_content = "Ryza...",
  ui_story_5085_50851100_18_dialog_content = "Dia benar-benar berhasil berbuat lebih dari harapanku kali ini...",
  ui_story_5085_50851100_19_dialog_content = "Mari lihat apa yang bisa diceritakan oleh fragmen terakhir dari reruntuhan itu kepada kita—",
  ui_story_5085_50851100_20_dialog_content = "Kepada Yang Mulia Pangeran,",
  ui_story_5085_50851100_21_dialog_content = "Eclipsite telah menjadi lebih buas, dan kekuatan reruntuhan mulai memudar. Aku khawatir kerajaan pulau kita tidak akan bertahan lebih lama lagi.",
  ui_story_5085_50851100_22_dialog_content = "Dan dengan demikian, kami telah memutuskan untuk mengikuti jejak mulia Anda, dan memimpin rakyat kami ke daratan utama dalam mencari rumah baru.",
  ui_story_5085_50851100_23_dialog_content = "Kami mungkin tidak bisa menyanyikan pujian untukmu saat kembalinya kemenanganmu...",
  ui_story_5085_50851100_24_dialog_content = "Tetapi yakinlah bahwa orang-orangmu belum dikalahkan. Mereka hanya memilih untuk memulai lagi di tanah asing.",
  ui_story_5085_50851100_25_dialog_content = "May kita bertemu dan bersatu kembali satu sama lain di daratan yang cerah dan makmur.",
  ui_story_5085_50851100_26_dialog_content = "Jadi kerajaan itu tidak pernah dihapus sejak awal!",
  ui_story_5085_50851100_27_dialog_content = "Mereka melakukan perjalanan ke daratan utama Astra dan menemukan kehidupan baru di sana!",
  ui_story_5085_50851100_28_dialog_content = "Meskipun sang pangeran tidak pernah kembali dari petualangannya, tindakannya telah membuka jalan bagi kelangsungan hidup rakyatnya...",
  ui_story_5085_50851100_29_dialog_content = "Bukan hanya membuatnya menjadi seorang pangeran yang layak, tetapi juga seorang petualang yang berani!",
  ui_story_5085_50851100_30_dialog_content = "Jika keturunan mereka mengetahui semua ini... Apakah mereka akan mencoba untuk bersatu kembali di daratan utama?",
  ui_story_5085_50851100_32_dialog_content = "Tidak peduli berapa banyak waktu yang berlalu, hati mereka akan selalu bersatu. Bahkan, saya yakin mereka sudah bertemu kembali satu sama lain di suatu tempat.",
  ui_story_5085_50851100_33_dialog_content = "Aku pikir juga begitu! Aku bisa merasakan cinta yang membakar dan mengikat hati mereka bersama-sama!",
  ui_story_5085_50851100_34_dialog_content = "Ini mungkin bukan akhir yang sempurna untuk cerita mereka...",
  ui_story_5085_50851100_35_dialog_content = "Tapi ini masih bagus... Dan itu seharusnya lebih dari cukup.",
  ui_story_5085_50851100_36_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5085_50851100_37_dialog_content = "...",
  ui_story_5085_50851100_38_dialog_content = "Oh... Sepertinya ini saatnya kita mengucapkan selamat tinggal.",
  ui_story_5085_50851100_39_dialog_content = "Jika kita pernah mendapatkan kesempatan untuk bertemu lagi, saya ingin mendengar semua tentang petualangan Anda, PlayerName...",
  ui_story_5085_50851100_40_dialog_content = "Sayang sekali aku bahkan tidak bisa menggunakan alkimia untuk membuat hadiah perpisahan untuk setiap orang, tapi...",
  ui_story_5085_50851100_41_dialog_content = "Aku akan selalu menghargai petualangan kita hari ini lebih dari harta karun lainnya!",
  ui_story_5085_50851100_42_dialog_content = "S-Saya juga! Sungguh menyenangkan bisa mengenal setiap orang di sini! Dan Nyonya Barbara, tidak ada yang lebih saya inginkan selain melihat salah satu konsermu suatu hari nanti!",
  ui_story_5085_50851100_43_dialog_content = "Oh? Maka saya akan memastikan kamu mendapatkan perlakuan VIP terbaik yang bisa dibayangkan!",
  ui_story_5085_50851100_44_dialog_content = "Meski waktu kita bersama singkat... Aku tidak akan pernah melupakan kalian semua.",
  ui_story_5085_50851100_45_dialog_content = "Zarya! Mari kita berusaha sebaik mungkin dan terus berkembang!",
  ui_story_5085_50851100_46_dialog_content = "A-Aku juga tidak akan lupa, tapi... Tapi aku juga tidak akan kalah darimu, Patty!",
  ui_story_5085_50851100_47_dialog_content = "Aku tahu ini saatnya kita berpisah, tapi aku tidak bisa mengatakannya dengan keras...",
  ui_story_5085_50851100_48_dialog_content = "Jangan tampak begitu sedih, PlayerName! Saya yakin kita akan bertemu lagi suatu hari nanti!",
  ui_story_5085_50851100_49_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5085_50851100_50_dialog_content = "Anu…",
  ui_story_5085_50851100_51_dialog_content = "K-Kita masih di sini?!",
  ui_story_5085_50851100_52_dialog_content = "M-Maaf mengganggu, tapi saya rasa bisa kujelaskan!",
  ui_story_5085_50851100_53_dialog_content = "Fleur? Tunggu... Kamu bukan masih pangeran, bukan?",
  ui_story_5085_50851100_54_dialog_content = "Tidak, saya cukup yakin saya masih Fleur.",
  ui_story_5085_50851100_55_dialog_content = "\"Cukup yakin\"?!",
  ui_story_5085_50851100_56_dialog_content = "Benar, meski aku memiliki pesan untuk setiap orang dari pangeran...",
  ui_story_5085_50851100_57_dialog_content = "Berkat usaha Anda, akhirnya dia mengetahui bahwa orang-orang yang dia sayangi berhasil selamat meninggalkan pulau tersebut, dan memulai kehidupan baru di daratan Astra.",
  ui_story_5085_50851100_58_dialog_content = "Dia juga dengan tulus meminta maaf karena telah membuat begitu banyak masalah bagi semua orang.",
  ui_story_5085_50851100_59_dialog_content = "Sebagai tanda niat baik, dia menggunakan kekuatan terakhir yang tersisa dari reruntuhan...",
  ui_story_5085_50851100_60_dialog_content = "Untuk menjaga kalian bertiga di dunia kami sedikit lebih lama!",
  ui_story_5085_50851100_61_dialog_content = "Sayangnya, reruntuhan itu tidak memiliki banyak daya tersisa di dalamnya, dan sebentar lagi efeknya akan hilang.",
  ui_story_5085_50851100_62_dialog_content = "Tapi setidaknya, kamu akan bisa menikmati petualangan musim panas yang menyenangkan di sini di Astra!",
  ui_story_5085_50851100_63_dialog_content = "Hah?!",
  ui_story_5085_50851100_64_dialog_content = "Itu bagus dan semua... Tapi bukankah seharusnya dia yang paling harus minta maaf padamu?",
  ui_story_5085_50851100_65_dialog_content = "Ah, tidak perlu khawatir tentang itu. Dia sudah memberikan pengetahuan tentang mecha itu kepadaku!",
  ui_story_5085_50851100_66_dialog_content = "Begitu kita sampai di rumah, aku akan bisa membuat sesuatu yang benar-benar luar biasa.",
  ui_story_5085_50851100_67_dialog_content = "(Tunggu, itu berarti dia benar-benar marah ketika kita menghancurkannya sebelumnya!)",
  ui_story_5085_50851100_68_dialog_content = "Omong-omong... Sepertinya kita tidak memahami intinya...",
  ui_story_5085_50851100_69_dialog_content = "Lalu... Apakah ini berarti aku bisa tinggal di duniamu sedikit lebih lama?!",
  ui_story_5085_50851100_70_dialog_content = "Dalam hal ini, saya ingin melihat semua yang ditawarkan oleh dunia ini! Colossus, Gurun Rediesel, Lumopolis... Kamu bisa menunjukkan semua itu dan lebih banyak lagi, bukan Navigator?!",
  ui_story_5085_50851100_71_dialog_content = "Tentu saja! Kalian sekarang adalah teman dekat kami, serta orang-orang yang telah menyelamatkan nyawa kami sebelumnya.",
  ui_story_5085_50851100_72_dialog_content = "Sebagai Navigator Colossus, akan menjadi kehormatan saya untuk menyambut ketiga dari kalian di kapal!",
  ui_story_5085_50851100_73_dialog_content = "Wow, terima kasih banyak! Aku tak sabar untuk menjalani berbagai petualangan di duniamu!",
  ui_story_5085_50851100_74_dialog_content = "Mari bersenang-senang sebanyak mungkin sebelum saatnya untuk mengucapkan selamat tinggal!",
  ui_story_5085_50851100_76_dialog_content = "Saya mengandalkanmu untuk menunjukkan dunia ini, Navigator! Baiklah, mari kita pergi!",
  ui_story_5085_50851100_77_dialog_content = "Ryza, Navigator... May Bolehkah aku bergabung denganmu juga?",
  ui_story_5085_50851100_78_dialog_content = "Jangan lupakan aku!",
  ui_story_5085_50851100_79_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_5085_50851100_80_dialog_content = "<color=#e8d9bb>Pulau itu terletak dengan sunyi di dasar laut, bersama dengan bukti kejayaan masa lalunya. Sekarang, petualangan musim panas baru akan dimulai.</color>",
  ui_story_5085_50851100_81_dialog_content = "Berhenti berikutnya: Astra! Berlayar penuh ke depan!"
}
return config
